<template>
  <!-- 外層仍滿版，左右黑邊由這層背景色露出 -->
  <section
    class="fixed inset-0 bg-gray-900 overflow-hidden w-full h-full z-50 select-none"
  >
    <!-- 置中顯示區（桌機限制最大寬度；手機 100vw） -->
    <div
      ref="contentFrame"
      class="absolute inset-y-0 left-1/2 -translate-x-1/2 w-full h-full"
      :style="contentFrameStyle"
    >
      <!-- 背景（模糊 or 一般） -->
      <canvas
        ref="bgCanvas"
        class="absolute inset-0 block w-full h-full z-[5]"
      />
      <!-- 清晰區域 / 人像 -->
      <canvas
        ref="outputCanvas"
        class="absolute inset-0 block w-full h-full z-[20]"
      />

      <!-- ✅ 月亮影片（所有裝置統一使用 <source> 列表：MOV(hvc1) → WEBM → MP4）
           桌機（Safari）會優先吃 .mov；不支援者自動 fallback -->
      <div
        v-if="hasPerson"
        class="absolute pointer-events-none z-[15]"
        :style="contentAreaStyle"
      >
        <video
          ref="moonVideoEl"
          class="w-full h-full object-contain force-composite"
          autoplay
          loop
          muted
          playsinline
          webkit-playsinline
          preload="auto"
          style="
            pointer-events: none;
            background: transparent;
            transform: translateZ(0);
            filter: opacity(1);
            backface-visibility: hidden;
          "
        >
          <!-- MOV with alpha (hvc1) 先給 -->
          <source
            :src="basePath + 'moon_alpha_ios.mov'"
            type='video/mp4; codecs="hvc1"'
          />
          <!-- 再給 webm -->
          <source :src="basePath + 'moon.webm'" type="video/webm" />
          <!-- 最後 mp4 當保底 -->
          <source :src="basePath + 'moon.mp4'" type="video/mp4" />
        </video>
      </div>

      <!-- ⚠️（保留）月亮影片 - 其他設備使用 CSS Mask（目前關閉，要用把 false 拿掉） -->
      <div
        v-if="false && hasPerson && deviceType === 'other'"
        class="moon-mask-container absolute pointer-events-none z-[15]"
        :style="contentAreaStyle"
        ref="moonMaskContainer"
      >
        <video
          ref="moonVideoMask"
          class="moon-video-masked w-full h-full"
          autoplay
          loop
          muted
          playsinline
          webkit-playsinline
          style="pointer-events: none"
          @loadedmetadata="onMoonVideoLoaded"
        >
          <!-- 一樣維持 MOV → WEBM → MP4 的來源順序 -->
          <source
            :src="basePath + 'moon_alpha_ios.mov'"
            type='video/mp4; codecs="hvc1"'
          />
          <source :src="basePath + 'moon.webm'" type="video/webm" />
          <source :src="basePath + 'moon.mp4'" type="video/mp4" />
        </video>
      </div>

      <!-- 框架和文字容器：移除負 margin，使用穩定的相對定位 -->
      <div
        ref="frameContainer"
        class="absolute inset-0 pointer-events-none z-[30]"
        style="-webkit-text-size-adjust: 100%; text-size-adjust: 100%"
      >
        <!-- PNG 框（統一使用 object-contain 避免縮放問題） -->
        <img
          v-if="currentBackground.frame"
          :src="basePath + currentBackground.frame"
          ref="frameImgEl"
          alt="裝飾框架"
          class="absolute inset-0 w-full h-full object-contain pointer-events-none"
          @error="handleFrameError"
          @load="handleFrameLoad"
        />

        <!-- 文字層：使用百分比定位和 CSS 變數縮放 -->
        <div class="absolute inset-0 pointer-events-none z-[5]">
          <div
            class="absolute text-white font-sans tracking-wider whitespace-nowrap"
            :style="dateTextStyle"
          >
            {{ currentDate }}
          </div>
          <div
            class="absolute text-white font-sans tracking-wider whitespace-nowrap"
            :style="nameTextStyle"
          >
            {{ userName || "Guest" }}
          </div>
        </div>
      </div>

      <!-- 底部控制列（限制在 content-frame 內） -->
      <div
        v-show="!isProcessing && !resourcesLoading"
        class="absolute left-0 right-0 z-[40] pt-4 pb-6"
        :style="{
          bottom: `calc(env(safe-area-inset-bottom,0px) + 0px)`,
          paddingBottom: `calc(1rem + env(safe-area-inset-bottom,0px))`,
        }"
      >
        <!-- 輪播指示點 -->
        <div class="flex items-center justify-center gap-2 mb-1">
          <span
            v-for="(bg, i) in availableBackgrounds"
            :key="bg.id || i"
            class="inline-block w-2.5 h-2.5 rounded-full transition-opacity"
            :class="i === currentBackgroundIndex ? 'bg-white' : 'bg-white/40'"
          />
        </div>

        <!-- 左右切換提示列 -->
        <div class="flex items-center justify-center mb-4">
          <button
            @click="prevBackground"
            class="grid place-items-center w-14 aspect-square rounded-full text-white active:scale-95 select-none"
            aria-label="上一個"
          >
            <svg
              class="w-7 h-7"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              stroke-width="2"
              stroke-linecap="round"
              stroke-linejoin="round"
            >
              <polyline points="15 18 9 12 15 6" />
            </svg>
          </button>

          <div
            class="px-4 py-1.5 rounded-full text-white/90 font-medium text-base md:text-lg tracking-[0.25em] select-none"
          >
            {{ hasPerson ? "左右點擊選取款式" : "左右點擊選取框架" }}
          </div>

          <button
            @click="nextBackground"
            class="grid place-items-center w-14 aspect-square rounded-full text-white active:scale-95 select-none"
            aria-label="下一個"
          >
            <svg
              class="w-7 h-7"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              stroke-width="2"
              stroke-linecap="round"
              stroke-linejoin="round"
            >
              <polyline points="9 18 15 12 9 6" />
            </svg>
          </button>
        </div>

        <!-- 下：操作按鈕 -->
        <div class="px-4 sm:px-6 btn-row">
          <div
            class="mx-auto w-full max-w-[600px] flex items-center justify-center gap-3 sm:gap-4"
          >
            <button
              @click="downloadPhoto"
              class="flex-1 basis-[clamp(140px,45%,180px)] py-3 bg-white text-black rounded-[5px] font-medium text-[13px] sm:text-[15px] border border-gray-300 hover:bg-gray-100 transition-colors inline-flex items-center justify-center gap-1"
            >
              <span class="whitespace-nowrap">收藏探月護照</span>
              <svg
                class="w-3 h-3 sm:w-4 sm:h-4"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                stroke-width="2"
                stroke-linecap="round"
                stroke-linejoin="round"
              >
                <polyline points="9 18 15 12 9 6" />
              </svg>
            </button>

            <button
              @click="sharePhoto"
              class="flex-1 basis-[clamp(140px,45%,180px)] py-3 bg-white text-black rounded-[5px] font-medium text-[13px] sm:text-[15px] border border-gray-300 hover:bg-gray-100 transition-colors inline-flex items-center justify-center gap-1"
            >
              <span class="whitespace-nowrap">分享給好友</span>
              <svg
                class="w-3 h-3 sm:w-4 sm:h-4"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                stroke-width="2"
                stroke-linecap="round"
                stroke-linejoin="round"
              >
                <polyline points="9 18 15 12 9 6" />
              </svg>
            </button>
          </div>
        </div>
      </div>
    </div>

    <!-- 處理中/載入中遮罩（全畫面覆蓋，和之前一樣） -->
    <div
      v-if="isProcessing"
      class="absolute inset-0 flex items-center justify-center bg-black/50 z-[45]"
    >
      <div class="text-white text-center">
        <div
          class="animate-spin rounded-full h-12 w-12 border-b-2 border-white mx-auto mb-4"
        ></div>
        <p class="text-lg">合成中...</p>
      </div>
    </div>
    <div
      v-if="resourcesLoading && !isProcessing"
      class="absolute inset-0 flex items-center justify-center bg-black/60 z-[45]"
    >
      <div class="text-white text-center">
        <div
          class="animate-spin rounded-full h-12 w-12 border-b-2 border-white mx-auto mb-4"
        ></div>
        <p class="text-lg">載入中...</p>
        <!-- 進度計數器已隱藏，但背景仍會計算載入進度 -->
      </div>
    </div>

    <!-- 隱藏元素（預載用；同樣給 MOV → WEBM → MP4） -->
    <div class="hidden">
      <video
        ref="bgMoonVideoEl"
        class="bg_video"
        muted
        loop
        preload="auto"
        playsinline
        style="display: none"
      >
        <source
          :src="basePath + 'moon_alpha_ios.mov'"
          type='video/mp4; codecs="hvc1"'
        />
        <source :src="basePath + 'moon.webm'" type="video/webm" />
        <source :src="basePath + 'moon.mp4'" type="video/mp4" />
      </video>
    </div>
  </section>
</template>

<script>
import { ref, computed, onMounted, onBeforeUnmount, nextTick } from "vue";

export default {
  name: "PhotoPreview",
  props: {
    originalImageData: { type: [String, Object], required: true },
    availableBackgrounds: { type: Array, required: true },
    selectedBackground: { type: String, required: true },
    userName: { type: String, default: "" },
    hasPerson: { type: Boolean, default: true },
    /** 桌機版互動區最大寬度（px），手機不受影響 */
    desktopMaxWidth: { type: [Number, String], default: 480 },
  },
  emits: ["close", "background-change"],
  setup(props, { emit }) {
    // Refs
    const contentFrame = ref(null);
    const frameContainer = ref(null);
    const bgCanvas = ref(null);
    const outputCanvas = ref(null);
    const moonVideoEl = ref(null);
    const moonVideoMask = ref(null);
    const moonMaskContainer = ref(null);
    const bgMoonVideoEl = ref(null);
    const frameImgEl = ref(null);

    // State
    const isProcessing = ref(false);
    const resourcesLoading = ref(true);
    // ✅ 分享素材快取（預先產生避免第一次分享失敗）
    const shareAsset = ref(null); // { blob, url, mime, fileName, file, type: 'video'|'image' }
    const preparingShare = ref(false); // 內部用，避免重複產生
    const resourceLoadCount = ref(0);
    const totalResourceCount = ref(0);
    const currentBackgroundIndex = ref(0);

    // Base path
    const basePath = computed(() => import.meta.env.BASE_URL || "/");

    // 置中 content-frame 寬度
    const contentFrameStyle = computed(() => ({
      width: `min(100vw, ${Number(props.desktopMaxWidth) || 480}px)`,
      height: "100%",
    }));

    // content-frame 尺寸（桌機上作為所有計算基準；手機等於視窗）
    const frameSize = ref({ w: 0, h: 0 });
    const measureFrame = () => {
      const rect = contentFrame.value?.getBoundingClientRect?.();
      frameSize.value = {
        w: Math.round(rect?.width || window.innerWidth || 0),
        h: Math.round(rect?.height || window.innerHeight || 0),
      };
    };

    // 設備類型偵測（保留，供日後要開 CSS Mask 時用）
    const deviceType = computed(() => {
      const userAgent = navigator.userAgent.toLowerCase();
      const isIOS = /iphone|ipad|ipod/.test(userAgent);
      const isAndroid = /android/.test(userAgent);
      if (isIOS) return "ios";
      if (isAndroid) return "android";
      return "other";
    });

    // CSS Mask 相關參數 (正規化座標)
    const maskParams = ref({ nx: 0.5, ny: 0.3, nr: 0.15, featherRatio: 0.03 });

    // iOS 裝置（保留向後相容欄位）
    const isIOSDevice = computed(() => deviceType.value === "ios");

    // 更新 CSS Mask 參數（以 content-frame 尺寸計）
    const updateMask = () => {
      if (!moonMaskContainer.value) return;
      const container = moonMaskContainer.value;
      const minSide = Math.min(frameSize.value.w, frameSize.value.h);
      container.style.setProperty(
        "--cx",
        (maskParams.value.nx * 100).toFixed(4)
      );
      container.style.setProperty(
        "--cy",
        (maskParams.value.ny * 100).toFixed(4)
      );
      container.style.setProperty(
        "--rpx",
        maskParams.value.nr * minSide + "px"
      );
      container.style.setProperty(
        "--featherpx",
        maskParams.value.featherRatio * minSide + "px"
      );
    };

    // 月亮影片載入完成處理（僅 CSS Mask 版會用到）
    const onMoonVideoLoaded = () => {
      if (!moonVideoMask.value || !moonMaskContainer.value) return;
      updateMask();
    };

    // Background
    const currentBackground = computed(() => {
      return (
        props.availableBackgrounds[currentBackgroundIndex.value] ||
        props.availableBackgrounds[0]
      );
    });

    // Constants
    const BLUR_PX = 6;
    const MOON_OFFSET_PCT = 0.06;

    // 設計稿基準尺寸（假設你的框架設計基準）
    const DESIGN_BASE_W = 480;
    const DESIGN_BASE_H = 854;

    // 文字設計稿座標（請根據實際設計稿調整）
    const DATE_DESIGN = { x: 135, y: 610, fontPx: 18 }; // 日期在設計稿的位置和字級
    const NAME_DESIGN = { x: 270, y: 610, fontPx: 18 }; // 名字在設計稿的位置和字級

    // 框架自然尺寸和實際顯示矩形
    const frameNatural = ref({ w: DESIGN_BASE_W, h: DESIGN_BASE_H });
    const frameRect = ref({ x: 0, y: 0, w: 0, h: 0 });

    // 計算 object-contain 後的實際矩形
    function containRect(W, H, mediaW, mediaH) {
      const s = Math.min(W / mediaW, H / mediaH);
      const w = mediaW * s,
        h = mediaH * s;
      return { x: (W - w) / 2, y: (H - h) / 2, w, h };
    }

    // 更新框架尺寸和 CSS 變數
    const updateFrameMetrics = () => {
      const el = frameContainer.value;
      if (!el) return;
      const { width: W, height: H } = el.getBoundingClientRect();
      const { w: mw, h: mh } = frameNatural.value;
      const r = containRect(W, H, mw, mh);
      frameRect.value = r;
      // 寫入 CSS 變數（px），以及縮放倍數（相對設計稿寬度）
      el.style.setProperty("--frame-x", `${r.x}px`);
      el.style.setProperty("--frame-y", `${r.y}px`);
      el.style.setProperty("--frame-w", `${r.w}px`);
      el.style.setProperty("--frame-h", `${r.h}px`);
      el.style.setProperty("--frame-scale", `${r.w / DESIGN_BASE_W}`);
    };

    // 工具：px -> %
    const toPercent = (px, base) => `${(px / base) * 100}%`;

    // 取得「在 Canvas 尺寸下」的框矩形（與 DOM 的 frameRect 對齊）
    function frameRectInCanvas(W, H) {
      const { w: mw, h: mh } = frameNatural.value; // 取實際框圖 natural 尺寸
      const s = Math.min(W / mw, H / mh);
      const w = mw * s,
        h = mh * s;
      return { x: (W - w) / 2, y: (H - h) / 2, w, h };
    }

    // 根據設計稿座標產生樣式（使用框矩形變數）
    const styleFromDesign = (design) => {
      const pxX = (design.x / DESIGN_BASE_W).toFixed(6);
      const pxY = (design.y / DESIGN_BASE_H).toFixed(6);
      return {
        left: `calc(var(--frame-x) + var(--frame-w) * ${pxX})`,
        top: `calc(var(--frame-y) + var(--frame-h) * ${pxY})`,
        transform: "translate(-50%, -50%)",
        fontSize: `calc(var(--frame-scale) * ${design.fontPx}px)`,
        letterSpacing: design.letterPx
          ? `calc(var(--frame-scale) * ${design.letterPx}px)`
          : undefined,
        textShadow: "0 1px 2px rgba(0,0,0,.6)",
      };
    };

    const handleFrameLoad = (e) => {
      const img = e?.target || frameImgEl.value;
      if (img?.naturalWidth && img?.naturalHeight) {
        frameNatural.value = { w: img.naturalWidth, h: img.naturalHeight };
      }
      renderPreview();
      updateFrameMetrics();
      // ⬇️ 新增：預先產生分享素材
      ensureShareAssetReady().catch(() => {});
    };
    const handleFrameError = () => {
      /* 靜默 */
    };

    // ResizeObserver 監聽容器尺寸變化
    let resizeObserver = null;

    onMounted(() => {
      measureFrame();
      updateFrameMetrics();
      window.addEventListener("resize", onResize);

      // 設置 ResizeObserver 監聽框架容器
      if (frameContainer.value) {
        resizeObserver = new ResizeObserver(updateFrameMetrics);
        resizeObserver.observe(frameContainer.value);
      }

      nextTick(() => {
        // 不再手動指定 bgMoonVideoEl.src，改由 <source> 自行挑格式
        if (deviceType.value === "other" && props.hasPerson) {
          setTimeout(updateMask, 100);
        }
        setTimeout(initPreview, 50);
      });
    });
    onBeforeUnmount(() => {
      window.removeEventListener("resize", onResize);
      if (resizeObserver && frameContainer.value) {
        resizeObserver.unobserve(frameContainer.value);
        resizeObserver = null;
      }
      if (moonVideoEl.value && !moonVideoEl.value.paused)
        moonVideoEl.value.pause();
      if (moonVideoMask.value && !moonVideoMask.value.paused)
        moonVideoMask.value.pause();
    });
    const onResize = () => {
      measureFrame();
      updateFrameMetrics();
      renderPreview();
      updateMask();
    };

    // 工具：計算 object-cover 後的實際顯示矩形
    function coverRect(W, H, mediaW, mediaH) {
      if (!W || !H || !mediaW || !mediaH) return { x: 0, y: 0, w: W, h: H };
      const scale = Math.max(W / mediaW, H / mediaH);
      const w = Math.round(mediaW * scale);
      const h = Math.round(mediaH * scale);
      return { x: Math.round((W - w) / 2), y: Math.round((H - h) / 2), w, h };
    }

    // 日期/名字定位（使用百分比定位和響應式縮放）
    const currentDate = computed(() => {
      const now = new Date();
      return `${now.getFullYear()}.${String(now.getMonth() + 1).padStart(
        2,
        "0"
      )}.${String(now.getDate()).padStart(2, "0")}`;
    });

    const dateTextStyle = computed(() => styleFromDesign(DATE_DESIGN));
    const nameTextStyle = computed(() => styleFromDesign(NAME_DESIGN));

    // 月亮影片 DOM 區域（以框矩形為座標系，和文字對齊）
    const contentAreaStyle = computed(() => {
      const area = currentBackground.value?.contentArea;
      if (!area) return { display: "none" };
      const r = frameRect.value; // 👈 以框矩形為基準
      const moonScale = currentBackground.value?.moonScale ?? 1;

      const baseW = area.width * r.w;
      const baseH = area.height * r.h;
      const baseL = r.x + area.x * r.w;
      const baseT = r.y + area.y * r.h;

      const w = baseW * moonScale;
      const h = baseH * moonScale;
      const l = baseL - (w - baseW) / 2;
      const t = baseT - (h - baseH) / 2 + r.h * MOON_OFFSET_PCT;

      return {
        position: "absolute",
        left: `${l}px`,
        top: `${t}px`,
        width: `${w}px`,
        height: `${h}px`,
      };
    });

    // 初始化
    const initPreview = async () => {
      if (!bgCanvas.value || !outputCanvas.value) return;

      try {
        // 計算需要載入的資源數量
        let resourceCount = 0;

        // 人像圖片
        let imageData = props.originalImageData;
        if (typeof imageData === "object" && imageData?.segmentedImageData)
          imageData = imageData.segmentedImageData;
        else if (typeof imageData === "object" && imageData?.originalImageData)
          imageData = imageData.originalImageData;
        if (imageData) resourceCount++;

        // 背景圖片（有人像時）
        if (props.hasPerson && currentBackground.value?.src) resourceCount++;

        // 框架圖片
        if (currentBackground.value?.frame) resourceCount++;

        // 月亮影片（有人像時）
        if (props.hasPerson) resourceCount++;

        // 原始圖片（無人像時）
        if (!props.hasPerson && props.originalImageData) resourceCount++;

        resetResourceLoader(resourceCount);

        const loadPromises = [];

        // 載入人像圖片
        if (imageData) loadPromises.push(loadImageSafe(imageData, true));

        // 載入背景圖片
        if (props.hasPerson && currentBackground.value?.src) {
          loadPromises.push(
            loadImageSafe(basePath.value + currentBackground.value.src, true)
          );
        }

        // 載入框架圖片
        if (currentBackground.value?.frame) {
          loadPromises.push(
            loadImageSafe(basePath.value + currentBackground.value.frame, true)
          );
        }

        // 載入原始圖片（無人像時）
        if (!props.hasPerson && props.originalImageData) {
          let originalSrc = props.originalImageData;
          if (
            typeof originalSrc === "object" &&
            originalSrc?.originalImageData
          ) {
            originalSrc = originalSrc.originalImageData;
          }
          loadPromises.push(loadImageSafe(originalSrc, true));
        }

        // ✅ 月亮影片（統一用 moonVideoEl；CSS Mask 關閉中）
        if (props.hasPerson) {
          const moonVideo = moonVideoEl.value;
          if (moonVideo) loadPromises.push(ensureVideoReady(moonVideo, true));
          else incrementResourceCount();
        }

        await Promise.all(loadPromises);

        await new Promise((resolve) => {
          const check = () =>
            resourcesLoading.value ? setTimeout(check, 50) : resolve();
          check();
        });

        await renderPreview();
        // ⬇️ 新增：不阻塞 UI，背景預產分享素材
        setTimeout(() => {
          ensureShareAssetReady().catch(() => {});
        }, 0);

        if (props.hasPerson && moonVideoEl.value) {
          try {
            await moonVideoEl.value.play();
          } catch {}
        }
      } catch (e) {
        console.warn("預覽初始化失敗:", e);
        resourcesLoading.value = false;
      }
    };

    // 切換背景/框
    const switchBackground = async (dir = 1) => {
      const total = props.availableBackgrounds.length || 1;
      currentBackgroundIndex.value =
        (currentBackgroundIndex.value + dir + total) % total;
      emit("background-change", currentBackground.value.id);

      let resourceCount = 0;
      if (props.hasPerson && currentBackground.value?.src) resourceCount++;
      if (currentBackground.value?.frame) resourceCount++;

      if (resourceCount > 0) {
        resetResourceLoader(resourceCount);
        const loadPromises = [];
        if (props.hasPerson && currentBackground.value?.src) {
          loadPromises.push(
            loadImageSafe(basePath.value + currentBackground.value.src, true)
          );
        }
        if (currentBackground.value?.frame) {
          loadPromises.push(
            loadImageSafe(basePath.value + currentBackground.value.frame, true)
          );
        }
        await Promise.all(loadPromises);
        await new Promise((resolve) => {
          const check = () =>
            resourcesLoading.value ? setTimeout(check, 50) : resolve();
          check();
        });
      }

      await renderPreview();
      // ⬇️ 新增：切換後強制重產
      ensureShareAssetReady({ force: true }).catch(() => {});
    };
    const prevBackground = () => switchBackground(-1);
    const nextBackground = () => switchBackground(1);

    // 觸控切換
    const touch = { x0: 0, y0: 0, moving: false };

    // 繪製預覽（以 content-frame 尺寸為基準）
    const renderPreview = async () => {
      const bgCtx = bgCanvas.value.getContext("2d");
      const outCtx = outputCanvas.value.getContext("2d");
      const W = frameSize.value.w;
      const H = frameSize.value.h;

      bgCanvas.value.width = outputCanvas.value.width = W;
      bgCanvas.value.height = outputCanvas.value.height = H;

      bgCtx.clearRect(0, 0, W, H);
      outCtx.clearRect(0, 0, W, H);

      if (props.hasPerson) {
        // 背景圖
        if (currentBackground.value?.src) {
          try {
            const bgImg = await loadImageSafe(
              basePath.value + currentBackground.value.src,
              false
            );
            if (bgImg) bgCtx.drawImage(bgImg, 0, 0, W, H);
            else {
              bgCtx.fillStyle = "#1a1a1a";
              bgCtx.fillRect(0, 0, W, H);
            }
          } catch {
            bgCtx.fillStyle = "#1a1a1a";
            bgCtx.fillRect(0, 0, W, H);
          }
        } else {
          bgCtx.fillStyle = "#1a1a1a";
          bgCtx.fillRect(0, 0, W, H);
        }

        // 人像（以 frameRect 為座標系）
        let imageData = props.originalImageData;
        if (typeof imageData === "object" && imageData?.segmentedImageData)
          imageData = imageData.segmentedImageData;
        else if (typeof imageData === "object" && imageData?.originalImageData)
          imageData = imageData.originalImageData;
        if (imageData) {
          try {
            const personImg = await loadImageSafe(imageData, false);
            if (personImg) {
              const r = frameRect.value; // DOM 已更新好的矩形
              const area = currentBackground.value.contentArea || {
                x: 0,
                y: 0,
                width: 1,
                height: 1,
              };
              const rect = {
                x: r.x + area.x * r.w + 25,
                y: r.y + area.y * r.h + 14,
                w: area.width * r.w - 50,
                h: area.height * r.h,
              };
              const topCropPx = r.h * 0.12; // 👈 想剪多少就改這裡（例：剪 12% 的框高）

              // 先裁切，再寬度對齊
              outCtx.save();
              outCtx.beginPath();
              outCtx.rect(rect.x, rect.y, rect.w, rect.h); // 先把 Moon Pass 區域當作裁切框
              outCtx.clip();
              drawFitWidth(
                outCtx,
                personImg,
                rect.x,
                rect.y,
                rect.w,
                rect.h,
                topCropPx
              ); // 寬度等比對齊
              outCtx.restore();
            }
          } catch {
            /* 靜默 */
          }
        }
      } else {
        // 無人像：背景使用拍照原圖（水平反轉修正），框與 contentArea 可切換
        let originalSrc = props.originalImageData;
        if (typeof originalSrc === "object" && originalSrc?.originalImageData)
          originalSrc = originalSrc.originalImageData;
        const originalImg = await loadImageSafe(originalSrc, false);
        if (!originalImg) {
          bgCtx.fillStyle = "#1a1a1a";
          bgCtx.fillRect(0, 0, W, H);
        } else {
          const cover = coverRect(
            W,
            H,
            originalImg.naturalWidth,
            originalImg.naturalHeight
          );
          const drawCovered = (ctx) => {
            const destX = W - (cover.x + cover.w); // 水平反轉對齊
            ctx.drawImage(
              originalImg,
              0,
              0,
              originalImg.naturalWidth,
              originalImg.naturalHeight,
              destX,
              cover.y,
              cover.w,
              cover.h
            );
          };
          // 模糊底
          bgCtx.save();
          bgCtx.filter = `blur(${BLUR_PX}px)`;
          bgCtx.translate(W, 0);
          bgCtx.scale(-1, 1);
          drawCovered(bgCtx);
          bgCtx.restore();

          // 清晰框內（依目前選到的框 contentArea）
          const area = currentBackground.value?.contentArea || {
            x: 0.05,
            y: 0.25,
            width: 0.9,
            height: 0.5,
          };
          const clearRect = {
            x: area.x * W,
            y: area.y * H,
            w: area.width * W,
            h: area.height * H,
          };

          outCtx.save();
          outCtx.beginPath();
          outCtx.rect(clearRect.x, clearRect.y, clearRect.w, clearRect.h);
          outCtx.clip();
          outCtx.translate(W, 0);
          outCtx.scale(-1, 1);
          drawCovered(outCtx);
          outCtx.restore();
        }
      }
      // PNG 框由 <img> 顯示（匯出時位圖化）
    };

    // ===== 匯出：無人像→圖片；有人像→影片 =====
    const generatePreviewImage = async () => {
      const cssW = Math.round(frameSize.value.w);
      const cssH = Math.round(frameSize.value.h);
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      const canvas = document.createElement("canvas");
      canvas.width = Math.round(cssW * dpr);
      canvas.height = Math.round(cssH * dpr);
      const ctx = canvas.getContext("2d");
      ctx.scale(dpr, dpr);

      let originalSrc = props.originalImageData;
      if (typeof originalSrc === "object" && originalSrc?.originalImageData)
        originalSrc = originalSrc.originalImageData;
      const originalImg = await loadImageSafe(originalSrc, false);
      const frameImg = await loadImageSafe(
        currentBackground.value?.frame
          ? basePath.value + currentBackground.value.frame
          : null,
        false
      );

      drawOneFrame(ctx, cssW, cssH, {
        bgImg: null,
        frameImg,
        personImg: null,
        originalImg,
        moonVid: null,
        personRect: { x: 0, y: 0, w: 0, h: 0 },
        moonRect: { x: 0, y: 0, w: 0, h: 0 },
        hasPerson: false,
        flipHorizontal: true,
      });

      const blob = await new Promise((res) =>
        canvas.toBlob(res, "image/png", 1)
      );
      const url = URL.createObjectURL(blob);
      return {
        blob,
        url,
        mime: "image/png",
        fileName: `range_rover_preview_${Date.now()}.png`,
      };
    };

    const generatePreviewVideo = async (durationMs = 5000) => {
      isProcessing.value = true;
      try {
        const cssW = Math.round(frameSize.value.w);
        const cssH = Math.round(frameSize.value.h);
        const dpr = Math.min(window.devicePixelRatio || 1, 2);
        const canvas = document.createElement("canvas");
        canvas.width = Math.round(cssW * dpr);
        canvas.height = Math.round(cssH * dpr);
        const ctx = canvas.getContext("2d");
        ctx.scale(dpr, dpr);

        const stream = canvas.captureStream(30);
        const mime = pickMimeType([
          "video/mp4;codecs=h264",
          "video/mp4",
          "video/webm;codecs=vp9",
          "video/webm;codecs=vp8",
          "video/webm",
        ]);
        if (!mime) throw new Error("此瀏覽器不支援 MediaRecorder 錄製影片");

        const chunks = [];
        const rec = new MediaRecorder(stream, {
          mimeType: mime,
          videoBitsPerSecond: 6_000_000,
        });
        rec.ondataavailable = (e) =>
          e.data && e.data.size && chunks.push(e.data);
        const done = new Promise((res) => {
          rec.onstop = () => {
            const type = mime.includes("mp4") ? "video/mp4" : "video/webm";
            const blob = new Blob(chunks, { type });
            const url = URL.createObjectURL(blob);
            res({
              blob,
              url,
              mime: type,
              fileName: `range_rover_preview_${Date.now()}.${
                type.includes("mp4") ? "mp4" : "webm"
              }`,
            });
          };
        });

        // 素材（有人像）
        const frameImg = await loadImageSafe(
          currentBackground.value?.frame
            ? basePath.value + currentBackground.value.frame
            : null,
          false
        );
        const bgImg = await loadImageSafe(
          currentBackground.value?.src
            ? basePath.value + currentBackground.value.src
            : null,
          false
        );
        let personSrc = props.originalImageData;
        if (typeof personSrc === "object" && personSrc?.segmentedImageData)
          personSrc = personSrc.segmentedImageData;
        else if (typeof personSrc === "object" && personSrc?.originalImageData)
          personSrc = personSrc.originalImageData;
        const personImg = await loadImageSafe(personSrc, false);

        // ✅ 這裡一律使用 moonVideoEl（MOV 優先，fallback 自動選）
        const moonVid = moonVideoEl.value;
        if (moonVid) {
          await ensureVideoReady(moonVid, false);
          try {
            await moonVid.play();
          } catch {}
        }

        const r = frameRectInCanvas(cssW, cssH);
        const area = currentBackground.value?.contentArea || {
          x: 0,
          y: 0,
          width: 1,
          height: 1,
        };
        const personRect = {
          x: r.x + area.x * r.w,
          y: r.y + area.y * r.h,
          w: area.width * r.w,
          h: area.height * r.h,
        };
        const moonScale = currentBackground.value?.moonScale ?? 1;
        const moonRect = {
          w: personRect.w * moonScale,
          h: personRect.h * moonScale,
          x: personRect.x - (personRect.w * (moonScale - 1)) / 2,
          y:
            personRect.y -
            (personRect.h * (moonScale - 1)) / 2 +
            r.h * MOON_OFFSET_PCT, // 以 frameRect 高度位移
        };

        rec.start(100);
        const start = performance.now();
        const loop = () => {
          const now = performance.now();
          drawOneFrame(ctx, cssW, cssH, {
            bgImg,
            frameImg,
            personImg,
            originalImg: null,
            moonVid,
            personRect,
            moonRect,
            hasPerson: true,
            flipHorizontal: false,
          });
          if (now - start < durationMs) requestAnimationFrame(loop);
          else rec.stop();
        };
        drawOneFrame(ctx, cssW, cssH, {
          bgImg,
          frameImg,
          personImg,
          originalImg: null,
          moonVid,
          personRect,
          moonRect,
          hasPerson: true,
          flipHorizontal: false,
        });
        requestAnimationFrame(loop);

        return await done;
      } finally {
        isProcessing.value = false;
      }
    };

    // 下載 / 分享
    const downloadPhoto = async () => {
      try {
        if (props.hasPerson) {
          // 影片優先用快取；沒有就走原本長版錄製（顯示遮罩）
          if (shareAsset.value?.type === "video") {
            const { url, fileName } = shareAsset.value;
            const a = document.createElement("a");
            a.download = fileName;
            a.href = url;
            a.click();
            return;
          }
          const { url, fileName } = await generatePreviewVideo(5000); // 你原本的顯示遮罩錄製
          const a = document.createElement("a");
          a.download = fileName;
          a.href = url;
          a.click();
        } else {
          // 照片
          if (shareAsset.value?.type === "image") {
            const { url, fileName } = shareAsset.value;
            const a = document.createElement("a");
            a.download = fileName;
            a.href = url;
            a.click();
            return;
          }
          const { url, fileName } = await generatePreviewImage();
          const a = document.createElement("a");
          a.download = fileName;
          a.href = url;
          a.click();
        }
      } catch {
        alert("下載失敗，請重試");
      }
    };
    const sharePhoto = async () => {
      // 嚴格條件：有人像＝必須是影片；無人像＝必須是圖片
      const expectType = props.hasPerson ? "video" : "image";

      // 若素材尚未準備好，避免在 user gesture 裡才去產生（會掉 user activation）
      if (!shareAsset.value || shareAsset.value.type !== expectType) {
        alert(
          props.hasPerson
            ? "影片準備中，請稍後再按一次分享"
            : "圖片準備中，請稍後再按一次分享"
        );
        // 背景啟動生成，下一次按即可
        ensureShareAssetReady({ force: true }).catch(() => {});
        return;
      }

      // 無 Web Share API：改下載（仍遵守類型）
      if (!navigator.share) {
        await downloadPhoto();
        return;
      }

      const asset = shareAsset.value;

      try {
        // 優先走「檔案分享」，不要用 blob: URL
        if (
          asset.file &&
          (navigator.canShare?.({ files: [asset.file] }) ?? true)
        ) {
          await navigator.share({
            files: [asset.file],
            title: "Range Rover Moon Festival",
          });
          return;
        }

        // 若裝置不支援影片檔案分享（但規格要求一定要影片），改成「直接下載影片」
        if (props.hasPerson && asset.type === "video") {
          const a = document.createElement("a");
          a.download = asset.fileName;
          a.href = asset.url;
          a.click();
          return;
        }

        // 否則（無人像、圖片不支援分享）→ 下載圖片
        await downloadPhoto();
      } catch (err) {
        console.warn("分享失敗：", err);
      }
    };

    // 小工具
    const pickMimeType = (cands) => {
      for (const t of cands) {
        try {
          if (MediaRecorder.isTypeSupported(t)) return t;
        } catch {}
      }
      return "";
    };
    const ensureVideoReady = (v, countAsResource = true) =>
      new Promise((res) => {
        if (!v) {
          if (countAsResource) incrementResourceCount();
          return res();
        }
        if (v.readyState >= 2) {
          if (countAsResource) incrementResourceCount();
          return res();
        }
        const onReady = () => {
          v.removeEventListener("loadeddata", onReady);
          v.removeEventListener("canplay", onReady);
          if (countAsResource) incrementResourceCount();
          res();
        };
        v.addEventListener("loadeddata", onReady, { once: true });
        v.addEventListener("canplay", onReady, { once: true });
      });
    // 資源載入管理
    const incrementResourceCount = () => {
      resourceLoadCount.value++;
      if (resourceLoadCount.value >= totalResourceCount.value) {
        setTimeout(() => {
          resourcesLoading.value = false;
        }, 200);
      }
    };
    const resetResourceLoader = (total) => {
      totalResourceCount.value = total;
      resourceLoadCount.value = 0;
      resourcesLoading.value = total > 0;
    };
    const loadImageSafe = (src, countAsResource = true) =>
      new Promise((resolve) => {
        if (!src) {
          if (countAsResource) incrementResourceCount();
          return resolve(null);
        }
        const img = new Image();
        img.crossOrigin = "anonymous";
        img.onload = () => {
          if (countAsResource) incrementResourceCount();
          resolve(img);
        };
        img.onerror = () => {
          if (countAsResource) incrementResourceCount();
          resolve(null);
        };
        img.src = src;
      });

    // ✅ 靜默錄製一段短影片（用來當分享素材），不顯示處理中遮罩
    const recordVideoAsset = async (
      durationMs = 2500,
      { bitrate = 3_000_000, fps = 30, dprCap = 1.5 } = {}
    ) => {
      const cssW = Math.round(frameSize.value.w);
      const cssH = Math.round(frameSize.value.h);
      const dpr = Math.min(window.devicePixelRatio || 1, dprCap);

      const canvas = document.createElement("canvas");
      canvas.width = Math.round(cssW * dpr);
      canvas.height = Math.round(cssH * dpr);
      const ctx = canvas.getContext("2d");
      ctx.scale(dpr, dpr);

      const mime = pickMimeType([
        "video/mp4;codecs=h264",
        "video/mp4",
        "video/webm;codecs=vp9",
        "video/webm;codecs=vp8",
        "video/webm",
      ]);
      if (!mime) throw new Error("此瀏覽器不支援 MediaRecorder 錄製影片");

      const stream = canvas.captureStream(fps);
      const chunks = [];
      const rec = new MediaRecorder(stream, {
        mimeType: mime,
        videoBitsPerSecond: bitrate,
      });
      rec.ondataavailable = (e) => e.data && e.data.size && chunks.push(e.data);
      const done = new Promise((res) => {
        rec.onstop = () => {
          const type = mime.includes("mp4") ? "video/mp4" : "video/webm";
          const blob = new Blob(chunks, { type });
          const url = URL.createObjectURL(blob);
          res({
            blob,
            url,
            mime: type,
            fileName: `range_rover_preview_${Date.now()}.${
              type.includes("mp4") ? "mp4" : "webm"
            }`,
          });
        };
      });

      // 準備素材
      const frameImg = await loadImageSafe(
        currentBackground.value?.frame
          ? basePath.value + currentBackground.value.frame
          : null,
        false
      );
      const bgImg = await loadImageSafe(
        currentBackground.value?.src
          ? basePath.value + currentBackground.value.src
          : null,
        false
      );

      let personSrc = props.originalImageData;
      if (typeof personSrc === "object" && personSrc?.segmentedImageData)
        personSrc = personSrc.segmentedImageData;
      else if (typeof personSrc === "object" && personSrc?.originalImageData)
        personSrc = personSrc.originalImageData;
      const personImg = await loadImageSafe(personSrc, false);

      const moonVid = moonVideoEl.value;
      if (moonVid) {
        await ensureVideoReady(moonVid, false);
        try {
          await moonVid.play();
        } catch {}
      }

      const r = frameRectInCanvas(cssW, cssH);
      const area = currentBackground.value?.contentArea || {
        x: 0,
        y: 0,
        width: 1,
        height: 1,
      };
      const personRect = {
        x: r.x + area.x * r.w,
        y: r.y + area.y * r.h,
        w: area.width * r.w,
        h: area.height * r.h,
      };
      const moonScale = currentBackground.value?.moonScale ?? 1;
      const moonRect = {
        w: personRect.w * moonScale,
        h: personRect.h * moonScale,
        x: personRect.x - (personRect.w * (moonScale - 1)) / 2,
        y:
          personRect.y -
          (personRect.h * (moonScale - 1)) / 2 +
          r.h * MOON_OFFSET_PCT,
      };

      // 錄製 loop
      rec.start(100);
      const start = performance.now();
      const loop = () => {
        const now = performance.now();
        drawOneFrame(ctx, cssW, cssH, {
          bgImg,
          frameImg,
          personImg,
          originalImg: null,
          moonVid,
          personRect,
          moonRect,
          hasPerson: true,
          flipHorizontal: false,
        });
        if (now - start < durationMs) requestAnimationFrame(loop);
        else rec.stop();
      };
      drawOneFrame(ctx, cssW, cssH, {
        bgImg,
        frameImg,
        personImg,
        originalImg: null,
        moonVid,
        personRect,
        moonRect,
        hasPerson: true,
        flipHorizontal: false,
      });
      requestAnimationFrame(loop);

      return await done;
    };

    // ✅ 預先產生分享素材：有人像→影片；沒人像→PNG
    const ensureShareAssetReady = async ({ force = false } = {}) => {
      if (preparingShare.value) return;
      if (shareAsset.value && !force) return;

      try {
        preparingShare.value = true;
        if (props.hasPerson) {
          const v = await recordVideoAsset(2500, {
            bitrate: 3_000_000,
            dprCap: 1.5,
          });
          const file = new File([v.blob], v.fileName, { type: v.mime });
          shareAsset.value = { ...v, file, type: "video" };
        } else {
          // 直接用你現有的 generatePreviewImage()
          const img = await generatePreviewImage();
          const file = new File([img.blob], img.fileName, { type: img.mime });
          shareAsset.value = { ...img, file, type: "image" };
        }
      } catch (e) {
        console.warn("預先產生分享素材失敗：", e);
        shareAsset.value = null;
      } finally {
        preparingShare.value = false;
      }
    };

    const drawContain = (ctx, media, x, y, w, h) => {
      const mw = media.videoWidth || media.naturalWidth || w;
      const mh = media.videoHeight || media.naturalHeight || h;
      if (!mw || !mh) return;
      const scale = Math.min(w / mw, h / mh);
      const dw = mw * scale,
        dh = mh * scale;
      const dx = x + (w - dw) / 2,
        dy = y + (h - dh) / 2;
      try {
        ctx.drawImage(media, 0, 0, mw, mh, dx, dy, dw, dh);
      } catch {}
    };

    // 新增：寬度對齊 + 等比例縮放（用於人像）
    const drawFitWidth = (ctx, media, x, y, w, h, topCropPx = 0) => {
      const mw = media.videoWidth || media.naturalWidth || w;
      const mh = media.videoHeight || media.naturalHeight || h;
      if (!mw || !mh) return;
      // 以「目標寬度」為基準做等比縮放
      const scale = w / mw;
      const dw = w; // 寬度完全貼齊 Moon Pass
      const dh = mh * scale; // 高度按比例
      const dx = x;
      const dy = y + (h - dh) / 2 - topCropPx; // 👈 往上推就會只剪上方
      try {
        ctx.drawImage(media, 0, 0, mw, mh, dx, dy, dw, dh);
      } catch {}
    };
    const drawCover = (ctx, img, x, y, w, h) => {
      const mw = img?.naturalWidth || w,
        mh = img?.naturalHeight || h;
      if (!mw || !mh) return;
      const scale = Math.max(w / mw, h / mh),
        dw = mw * scale,
        dh = mh * scale;
      const dx = x + (w - dw) / 2,
        dy = y + (h - dh) / 2;
      try {
        ctx.drawImage(img, 0, 0, mw, mh, dx, dy, dw, dh);
      } catch {}
    };
    const drawOneFrame = (
      ctx,
      W,
      H,
      {
        bgImg,
        frameImg,
        personImg,
        originalImg,
        moonVid,
        personRect,
        moonRect,
        hasPerson,
        flipHorizontal = false,
      }
    ) => {
      ctx.clearRect(0, 0, W, H);

      if (hasPerson) {
        if (bgImg) {
          try {
            ctx.drawImage(bgImg, 0, 0, W, H);
          } catch {
            ctx.fillStyle = "#1a1a1a";
            ctx.fillRect(0, 0, W, H);
          }
        } else {
          ctx.fillStyle = "#1a1a1a";
          ctx.fillRect(0, 0, W, H);
        }
        if (moonVid && moonVid.readyState >= 2)
          drawContain(
            ctx,
            moonVid,
            moonRect.x,
            moonRect.y,
            moonRect.w,
            moonRect.h
          );
        if (personImg) {
          ctx.save();
          ctx.beginPath();
          ctx.rect(personRect.x, personRect.y, personRect.w, personRect.h); // 匯出也裁切
          ctx.clip();
          drawFitWidth(
            ctx,
            personImg,
            personRect.x,
            personRect.y,
            personRect.w,
            personRect.h
          );
          ctx.restore();
        }
      } else {
        if (originalImg) {
          const cover = coverRect(
            W,
            H,
            originalImg.naturalWidth,
            originalImg.naturalHeight
          );
          ctx.save();
          ctx.filter = `blur(${BLUR_PX}px)`;
          if (flipHorizontal) {
            ctx.translate(W, 0);
            ctx.scale(-1, 1);
          }
          const destX = flipHorizontal ? W - (cover.x + cover.w) : cover.x;
          ctx.drawImage(
            originalImg,
            0,
            0,
            originalImg.naturalWidth,
            originalImg.naturalHeight,
            destX,
            cover.y,
            cover.w,
            cover.h
          );
          ctx.restore();
          const area = currentBackground.value?.contentArea || {
            x: 0.05,
            y: 0.25,
            width: 0.9,
            height: 0.5,
          };
          const clearRect = {
            x: area.x * W,
            y: area.y * H,
            w: area.width * W,
            h: area.height * H,
          };
          ctx.save();
          ctx.beginPath();
          ctx.rect(clearRect.x, clearRect.y, clearRect.w, clearRect.h);
          ctx.clip();
          if (flipHorizontal) {
            ctx.translate(W, 0);
            ctx.scale(-1, 1);
          }
          const destX2 = flipHorizontal ? W - (cover.x + cover.w) : cover.x;
          ctx.drawImage(
            originalImg,
            0,
            0,
            originalImg.naturalWidth,
            originalImg.naturalHeight,
            destX2,
            cover.y,
            cover.w,
            cover.h
          );
          ctx.restore();
        } else {
          ctx.fillStyle = "#1a1a1a";
          ctx.fillRect(0, 0, W, H);
        }
      }

      // 框（使用 drawContain 保持與 DOM 一致）
      if (frameImg) drawContain(ctx, frameImg, 0, 0, W, H);

      // 文字（使用框矩形座標系，與 DOM 保持一致）
      if (frameImg?.naturalWidth && frameImg?.naturalHeight) {
        const rect = containRect(
          W,
          H,
          frameImg.naturalWidth,
          frameImg.naturalHeight
        );
        const scale = rect.w / DESIGN_BASE_W;

        ctx.font = `${
          DATE_DESIGN.fontPx * scale
        }px "Land Rover Web", sans-serif`;
        ctx.fillStyle = "#fff";
        ctx.textBaseline = "top";
        ctx.textAlign = "left";
        ctx.shadowColor = "rgba(0,0,0,.6)";
        ctx.shadowBlur = 2;
        ctx.shadowOffsetY = 1;

        // 日期文字
        const dateX = rect.x + rect.w * (DATE_DESIGN.x / DESIGN_BASE_W);
        const dateY = rect.y + rect.h * (DATE_DESIGN.y / DESIGN_BASE_H);
        ctx.fillText(currentDate.value, dateX, dateY);

        // 名字文字
        ctx.font = `${
          NAME_DESIGN.fontPx * scale
        }px "Land Rover Web", sans-serif`;
        const nameX = rect.x + rect.w * (NAME_DESIGN.x / DESIGN_BASE_W);
        const nameY = rect.y + rect.h * (NAME_DESIGN.y / DESIGN_BASE_H);
        ctx.fillText(props.userName || "Guest", nameX, nameY);

        ctx.shadowColor = "transparent";
        ctx.shadowBlur = 0;
        ctx.shadowOffsetY = 0;
      }
    };

    return {
      // Refs
      contentFrame,
      frameContainer,
      bgCanvas,
      outputCanvas,
      moonVideoEl,
      moonVideoMask,
      moonMaskContainer,
      bgMoonVideoEl,
      frameImgEl,
      // State
      isProcessing,
      resourcesLoading,
      resourceLoadCount,
      totalResourceCount,
      currentBackgroundIndex,
      frameRect,
      frameNatural,
      // Data / UI
      basePath,
      currentBackground,
      currentDate,
      contentAreaStyle,
      dateTextStyle,
      nameTextStyle,
      contentFrameStyle,
      // Device
      deviceType,
      isIOSDevice,
      // Methods
      onMoonVideoLoaded,
      prevBackground,
      nextBackground,
      downloadPhoto,
      sharePhoto,
      // Debug
      handleFrameLoad,
      handleFrameError,
      // Prop passthrough
      hasPerson: props.hasPerson,
    };
  },
};
</script>

