<template>
  <div class="landing-page fixed inset-0 bg-black overflow-hidden">
    <!-- 互動與背景同一座標系（桌機置中、手機全寬） -->
    <div
      ref="contentFrame"
      class="absolute inset-y-0 left-1/2 -translate-x-1/2 w-full h-full"
      :style="contentFrameStyle"
    >
      <!-- 純背景圖（不含任何字/按鈕） -->
      <div
        ref="bgContainer"
        class="absolute inset-0 w-full h-full bg-cover bg-top bg-no-repeat"
        :style="{ backgroundImage: `url(${basePath}${blankBgPath})` }"
      ></div>

      <!-- Merged文字PNG層 - 置頂並帶淡化掃描效果 -->
      <img
        :src="basePath + 'backgrounds/merged.png'"
        alt="Range Rover標題文字"
        class="fade-scan absolute top-0 left-0 w-full select-none"
        style="height: auto; z-index: 1; pointer-events: none; object-fit: fill;"
      />

      <!-- 標題圖片（取代原本的標題和副標文字） -->
      <img
        :src="basePath + 'backgrounds/liffTitle.png'"
        alt="收錄共頻時刻 - 珍藏賞月旅途的影像"
        class="absolute select-none"
        :style="titleImageStyle"
      />

      <!-- 只有上下邊框的輸入框 -->
      <div class="absolute" :style="inputBoxStyle">
        <div class="relative h-full input-lines">
          <input
            v-model="userName"
            type="text"
            placeholder="輸 入 車 主 名 稱"
            class="w-full h-full px-3 text-center bg-transparent border-none text-white placeholder-white/80 focus:outline-none focus:placeholder-white/60 transition-all text-[clamp(14px,3.6vw,18px)] tracking-[0.2em]"
            @keyup.enter="startCamera"
            @input="validateUserName"
            :maxlength="12"
            autocomplete="off"
          />
        </div>
      </div>

      <!-- 白底按鈕 -->
      <button
        @click="startCamera"
        class="absolute bg-white text-gray-900 shadow-lg active:scale-[.98] transition
               inline-flex items-center justify-center gap-2"
        :style="buttonStyle"
        aria-label="開啟相機"
      >
        <span class="whitespace-nowrap">開啟相機</span>
        <svg class="w-4 h-4" viewBox="0 0 24 24" fill="none"
             stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">
          <polyline points="9 18 15 12 9 6" />
        </svg>
      </button>

      <!-- 底下提示文字 -->
      <p class="absolute text-center text-white/80" :style="hintStyle">
        為你的探月護照拍一張照片
      </p>
    </div>

    <!-- 載入中遮罩 -->
    <div v-if="isLoading" class="fixed inset-0 flex items-center justify-center z-50 bg-black bg-opacity-80">
      <div class="text-white text-center">
        <div class="animate-spin rounded-full h-12 w-12 border-b-2 border-white mx-auto mb-4"></div>
        <p class="text-lg">載入中...</p>
      </div>
    </div>

    <!-- 提醒 -->
    <div
      v-if="showReminder && !isLoading"
      class="fixed inset-0 flex items-center justify-center z-50 bg-black/40 backdrop-blur-sm"
    >
      <div class="bg-white/90 backdrop-blur-md rounded-lg px-8 py-6 mx-6 text-center shadow-2xl">
        <div class="text-gray-800 text-lg font-medium">請先輸入車主名稱！</div>
      </div>
    </div>
  </div>
</template>

<script>
import { ref, computed, onMounted } from 'vue'

export default {
  name: 'LandingPage',
  emits: ['start-camera'],
  props: {
    /** 桌機版互動區最大寬度（px），手機不受影響 */
    desktopMaxWidth: { type: [Number, String], default: 480 },
    /** 純背景圖相對於 BASE_URL 的路徑 */
    blankBgPath: { type: String, default: 'backgrounds/liffEntranceBgV2.png' }
  },
  setup(props, { emit }) {
    const userName = ref('')
    const basePath = computed(() => import.meta.env.BASE_URL || '/')
    const showReminder = ref(false)

    // ===== 尺寸與定位（% 以 9:16 手機視覺稿為基準） =====
    // 需要微調時改下面這些百分比
    const pos = {
      titleTop: 14,          // 標題頂部位置（%）
      titleWidth: 84,        // 標題寬度（%）

      subtitleTop: 20,       // 副標頂部位置（%）
      subtitleWidth: 84,

      inputLeft: 25,
      inputTop: 54.98,
      inputWidth: 50,
      inputHeight: 6.77,

      buttonLeft: 20.03,
      buttonTop: 76.82,
      buttonWidth: 60.07,
      buttonHeight: 6.71,

      hintTop: 86.5,         // 提示文字頂部位置（%）
      hintWidth: 84
    }

    // 置中 content frame：桌機 <= desktopMaxWidth，手機 100vw
    const contentFrameStyle = computed(() => ({
      width: `min(100vw, ${Number(props.desktopMaxWidth) || 480}px)`,
      height: '100%'
    }))

    // 標題圖片樣式（取代原本的標題和副標）
    const titleImageStyle = computed(() => ({
      top: `${pos.titleTop}%`,
      left: '50%',
      transform: 'translateX(-50%)',
      width: '58%',  // 設定為視窗/最大寬度的50%
      height: 'auto',
      zIndex: 2
    }))
    const hintStyle = computed(() => ({
      top: `${pos.hintTop}%`,
      left: '50%',
      transform: 'translateX(-50%)',
      width: `${pos.hintWidth}%`,
      fontSize: 'clamp(12px, 3.6vw, 15px)',
      letterSpacing: '0.2em'
    }))

    // 輸入框與按鈕位置
    const inputBoxStyle = computed(() => ({
      left: `${pos.inputLeft}%`,
      top: `${pos.inputTop}%`,
      width: `${pos.inputWidth}%`,
      height: `${pos.inputHeight}%`
    }))
    const buttonStyle = computed(() => ({
      left: '50%',
      top: `${pos.buttonTop}%`,
      transform: 'translateX(-50%)',
      width: '50%',
      height: `${pos.buttonHeight}%`,
      fontSize: '18px',
      fontFamily: '"Noto Sans TC", "Source Han Sans TC", "思源黑體", "PingFang TC", "Microsoft JhengHei", sans-serif',
      fontWeight: 'bold',
      letterSpacing: '0.15em'
    }))

    // ===== 載入狀態（預載背景圖、merged.png和liffTitle.png） =====
    const isLoading = ref(true)
    const loadedImageCount = ref(0)
    const totalImageCount = ref(3)
    const preload = (src) =>
      new Promise((resolve) => {
        const img = new Image()
        img.onload = () => { loadedImageCount.value++; resolve() }
        img.onerror = () => { loadedImageCount.value++; resolve() }
        img.src = src
      })
    onMounted(async () => {
      // 並行預載背景圖、merged.png和liffTitle.png
      await Promise.all([
        preload(basePath.value + props.blankBgPath),
        preload(basePath.value + 'backgrounds/merged.png'),
        preload(basePath.value + 'backgrounds/liffTitle.png')
      ])
      // 小延遲讓轉場柔順
      setTimeout(() => { isLoading.value = false }, 200)
    })

    // ===== 驗證車主名稱長度（中:1 英數:0.5，總長<=6）=====
    const validateUserName = (event) => {
      const input = event.target.value
      let charCount = 0
      for (let i = 0; i < input.length; i++) {
        const char = input[i]
        if (/[\u4e00-\u9fff\u3400-\u4dbf\uf900-\ufaff]/.test(char)) charCount += 1
        else charCount += 0.5
      }
      if (charCount > 6) {
        let newValue = ''
        let current = 0
        for (let i = 0; i < input.length; i++) {
          const ch = input[i]
          const w = /[\u4e00-\u9fff\u3400-\u4dbf\uf900-\ufaff]/.test(ch) ? 1 : 0.5
          if (current + w <= 6) { newValue += ch; current += w } else break
        }
        userName.value = newValue
        event.target.value = newValue
      }
    }

    const startCamera = () => {
      if (userName.value.trim()) emit('start-camera', userName.value.trim())
      else {
        showReminder.value = true
        setTimeout(() => { showReminder.value = false }, 1800)
      }
    }

    return {
      userName, basePath,
      // frame 與定位
      contentFrameStyle, titleImageStyle, inputBoxStyle, buttonStyle, hintStyle,
      // 載入
      isLoading, loadedImageCount, totalImageCount,
      // 提醒與事件
      showReminder, startCamera, validateUserName
    }
  }
}
</script>

<style scoped>
/* 字體沿用專案預設；如需強制指定，可在全域或此處覆蓋：
:root { --app-tc-font: "Noto Sans TC","PingFang TC","Microsoft JhengHei","Helvetica Neue",Arial,sans-serif; }
.landing-page { font-family: var(--app-tc-font, inherit); }
*/

.heading-glow {
  text-shadow:
    0 0 8px rgba(255, 255, 255, 0.25),
    0 0 18px rgba(154, 214, 255, 0.25);
}

.subtle {
  /* 低調一點的發光與更寬字距 */
  text-shadow: 0 0 10px rgba(255,255,255,0.15);
}

/* 只有上下 1px 的白線 */
.input-lines::before,
.input-lines::after {
  content: "";
  position: absolute;
  left: 0;
  width: 100%;
  height: 1px;
  background: rgba(255,255,255,0.9);
}
