.input-lines::after  { bottom: 0; }

/* iOS 點擊去除高亮 */
button, input {
  -webkit-tap-highlight-color: transparent;
}

/* ===== 加強版柔和透明度變化效果 ===== */
.fade-scan {
  /* 讓動畫更順暢 */
  will-change: opacity;
  transform: translateZ(0);

  /* 加強對比度的三段式漸變遮罩 */
  -webkit-mask-image:
    linear-gradient(90deg,
      black 0%,
      rgba(0,0,0,0.5) 12%,
      rgba(0,0,0,0.9) 25%,
      rgba(0,0,0,0.3) 37%,
      rgba(0,0,0,0.8) 50%,
      rgba(0,0,0,0.4) 62%,
      rgba(0,0,0,0.9) 75%,
      rgba(0,0,0,0.5) 87%,
      black 100%
    );
  mask-image:
    linear-gradient(90deg,
      black 0%,
      rgba(0,0,0,0.5) 12%,
      rgba(0,0,0,0.9) 25%,
      rgba(0,0,0,0.3) 37%,
      rgba(0,0,0,0.8) 50%,
      rgba(0,0,0,0.4) 62%,
      rgba(0,0,0,0.9) 75%,
      rgba(0,0,0,0.5) 87%,
      black 100%
    );

  /* 遮罩尺寸和動畫 */
  -webkit-mask-size: 180% 100%;
  mask-size: 180% 100%;
  animation: enhanced-wave 15s ease-in-out infinite alternate;
}

/* 加強版波浪動畫 - 更明顯的變化 */
@keyframes enhanced-wave {
  0% {
    -webkit-mask-position: -40% 0%;
    mask-position: -40% 0%;
  }
  100% {
    -webkit-mask-position: 140% 0%;
    mask-position: 140% 0%;
  }
}
</style>