<template>
  <!-- 固定定位 + 動態 viewport 尺寸 -->
  <section
    ref="stage"
    class="stage fixed inset-0 bg-gray-900 overflow-hidden w-[100dvw] h-[100dvh]"
    style="width:100vw;width:100dvw;height:100vh;height:100dvh"
  >
    <!-- 背景 canvas（滿版；月亮與特效在更底層 bgCanvas；相機不畫在這層） -->
    <canvas ref="bgCanvas" class="bg_canvas absolute inset-0 block w-full h-full z-[5]" />

    <!-- 內容框（桌機置中且限寬；相機 & 人像都只畫在這一塊） -->
    <div
      ref="contentFrame"
      class="content-frame absolute inset-y-0 left-1/2 -translate-x-1/2 relative z-[8]"
      :style="contentFrameStyle"
    >
      <!-- 蒙版預覽（僅除錯用） -->
      <canvas ref="maskCanvas" class="mask_canvas absolute inset-0 block w-full h-full z-[20]" />

      <!-- ✅ 月亮影片（提前掛載以便預載；瀏覽器會自動挑能播的來源） -->
      <div
        v-if="needMoon"
        class="absolute inset-0 pointer-events-none z-[30]"
      >
        <video
          ref="moonVideo"
          class="w-full h-full object-contain force-composite"
          autoplay
          loop
          muted
          playsinline
          webkit-playsinline
          preload="auto"
          style="pointer-events:none; background:transparent;"
        >
          <source :src="basePath + 'moon_alpha_ios.mov'" type='video/mp4; codecs="hvc1"' />
          <source :src="basePath + 'moon.webm'" type="video/webm" />
          <source :src="basePath + 'moon.mp4'" type="video/mp4" />
        </video>
      </div>

      <!-- ⚠️ 原本桌機 CSS Mask 版本：保留但關閉 -->
      <div
        v-if="false && deviceType === 'other' && uiCameraRunning && needMoon"
        class="moon-mask-container absolute inset-0 pointer-events-none z-[30]"
        ref="moonMaskContainer"
      >
        <video
          ref="moonVideoMask"
          class="moon-video-masked w-full h-full"
          autoplay
          loop
          muted
          playsinline
          webkit-playsinline
          style="pointer-events:none;"
          :src="basePath + 'moon.mp4'"
          @loadedmetadata="onMoonVideoLoaded"
        />
      </div>

      <!-- 前景輸出（相機 + 人像去背）— 永遠在最上層 -->
      <canvas
        ref="outputCanvas"
        class="output_canvas absolute inset-0 block w-full h-full z-[40]"
      />
    </div>

    <!-- 載入／啟動遮罩（直到：不需要月亮 或 月亮已就緒）AND 相機已啟動 才會消失 -->
    <div
      v-show="showLoadingOverlay"
      class="absolute inset-0 flex items-center justify-center z-[120] bg-gray-900/80"
    >
      <div class="text-center text-white">
        <div class="animate-spin rounded-full h-8 w-8 border-b-2 border-white mx-auto mb-4"></div>
        <p class="text-lg">{{ loadingText }}</p>
      </div>
    </div>

    <!-- 快門 -->
    <button
      v-show="showControls && uiCameraRunning"
      @click="$emit('capture-photo')"
      class="absolute bottom-12 sm:bottom-16 left-1/2 -translate-x-1/2 z-[110] flex items-center justify-center w-[80px] h-[80px] sm:w-[99px] sm:h-[99px]"
    >
      <img :src="shutterIcon" alt="拍照" class="w-full h-full max-w-none select-none pointer-events-none" />
    </button>

    <!-- 切換前後鏡頭按鈕（多鏡頭才顯示） -->
    <button
      v-show="showControls && uiCameraRunning && hasMultipleCamerasState"
      @click="$emit('switch-camera')"
      class="absolute bottom-12 sm:bottom-16 right-4 sm:right-8 z-[110] flex items-center justify-center w-[80px] h-[80px] sm:w-[99px] sm:h-[99px] bg-transparent rounded-full transition-transform active:scale-95"
    >
      <img :src="switchCameraIcon" alt="切換鏡頭" class="w-[40px] h-[40px] sm:w-[50px] sm:h-[50px] select-none pointer-events-none" />
    </button>

    <!-- 提示 -->
    <div
      v-show="showControls && uiCameraRunning && showHintText"
      class="absolute bottom-8 sm:bottom-12 left-1/2 -translate-x-1/2 z-[110] text-white text-center font-medium text-[16px] tracking-[0.18em] transition-opacity duration-500 whitespace-nowrap px-4"
      :class="{ 'opacity-0': !hintVisible }"
      :style="{
        textShadow:'0 2px 8px rgba(0,0,0,.55)',
        transform:`translate(-50%, 0) scale(${textScale})`,
        transformOrigin:'center center'
      }"
    >
      對準臉部拍照可解鎖彩蛋
    </div>
  </section>
</template>

<script>
import { ref, computed, onMounted, onBeforeUnmount, watch, toRefs, nextTick } from 'vue'
import shutterIcon from '@/assets/images/shutter.png'
import switchCameraIcon from '@/assets/images/switch-camera.svg'

export default {
  name: 'CameraStage',
  props: {
    backgroundType:  { type: String,  default: '' },
    isIOSDevice:     { type: Boolean, default: false },
    showControls:    { type: Boolean, default: true },
    cameraRunning:   { type: Boolean, default: false }, // 父層實際控制 getUserMedia
    desktopMaxWidth: { type: [Number, String], default: 480 },
    checkMultipleCameras: { type: Function, default: null } // 可選：父層自訂檢查
  },
  emits: ['capture-photo', 'share-video', 'download-video', 'switch-camera', 'ready-for-camera'],
  setup(props, { expose, emit }) {
    const { showControls, cameraRunning } = toRefs(props)

    const stage        = ref(null)
    const contentFrame = ref(null)
    const bgCanvas     = ref(null)
    const maskCanvas   = ref(null)
    const outputCanvas = ref(null)
    const moonVideo    = ref(null)
    const moonVideoMask = ref(null) // 保留
    const moonMaskContainer = ref(null) // 保留

    const showShareButton    = ref(false)
    const showDownloadButton = ref(false)
    const showHintText = ref(true)
    const hintVisible  = ref(true)
    const hasMultipleCamerasState = ref(false)

    const basePath = computed(() => import.meta.env.BASE_URL || '/')

    const contentFrameStyle = computed(() => {
      const maxPx = Number(props.desktopMaxWidth) || 480
      return { width: `min(100vw, ${maxPx}px)`, height: '100%', '--content-max-w': `${maxPx}px` }
    })

    // 設備類型偵測（保留）
    const deviceType = computed(() => {
      const ua = navigator.userAgent.toLowerCase()
      const isIOS = /iphone|ipad|ipod/.test(ua)
      const isLine = /line/.test(ua)
      const isCriOS = /crios/.test(ua)
      const isSafari = /safari/.test(ua) && !/chrome/.test(ua)
      const isAndroid = /android/.test(ua)
      const isTest = new URLSearchParams(location.search).get('test-mov') === '1'
      if ((isIOS && (isLine || isCriOS || isSafari)) || isTest) return 'ios'
      if (isAndroid) return 'android'
      return 'other'
    })

    const needMoon = computed(() =>
      ['moon_video','custom_moon_bg','person_overlay'].includes(props.backgroundType)
    )

    // --- 月亮預載控制 ---
    const moonReady = ref(false)
    const loadingText = computed(() => {
      if (needMoon.value && !moonReady.value) return '載入月亮特效中...'
      if (!cameraRunning.value) return '相機啟動中...'
      return '載入中...'
    })
    // 介面層面視為「相機已就緒」＝ 實際相機已跑 且（不需要月亮 或 月亮就緒）
    const uiCameraRunning = computed(() => {
      return !!(cameraRunning.value && (!needMoon.value || moonReady.value))
    })

    // 第一次成功啟動相機的旗標（之後即使相機停掉，也不要再顯示「相機啟動中」）
    const hadCameraRunOnce = ref(false)
    watch(cameraRunning, (running) => {
      if (running) hadCameraRunOnce.value = true
    })

    // 只在「第一次開機流程」或「相機已開但等月亮就緒」時顯示遮罩
    const showLoadingOverlay = computed(() => {
      if (!showControls.value) return false

      // 1 初次開機流程：尚未成功開過相機
      if (!hadCameraRunOnce.value) {
        if (!cameraRunning.value) return true            // 申請權限 / 建立串流中
        if (needMoon.value && !moonReady.value) return true // 相機已開，但等月亮預載
      }

      // 2 已開過相機：只在「相機已開」且「需要月亮但還沒就緒」時顯示
      if (cameraRunning.value && needMoon.value && !moonReady.value) return true

      return false
    })

    // 動態文字縮放
    const textScale = ref(1)
    const calculateTextScale = () => {
      const screenWidth = window.innerWidth
      const textWidth = 280
      const availableWidth = screenWidth - 32
      textScale.value = textWidth > availableWidth ? Math.max(0.7, availableWidth / textWidth) : 1
    }

    // 等待 <video> 可播放（可播放或可順暢播放兩者之一）
    const waitForVideoReady = (v) => {
      return new Promise((resolve) => {
        if (!v) return resolve(false)
        const done = () => { cleanup(); resolve(true) }
        const fallback = () => { cleanup(); resolve(true) } // 有些瀏覽器不觸發 canplaythrough
        const cleanup = () => {
          v.removeEventListener('canplaythrough', done)
          v.removeEventListener('canplay', done)
          v.removeEventListener('loadeddata', done)
          v.removeEventListener('loadedmetadata', meta)
        }
        const meta = () => {
          // metadata 已載，若 readyState >= 2 也算就緒
          if (v.readyState >= 2) done()
        }
        v.addEventListener('canplaythrough', done, { once: true })
        v.addEventListener('canplay', done, { once: true })
        v.addEventListener('loadeddata', done, { once: true })
        v.addEventListener('loadedmetadata', meta, { once: true })

        try { v.load() } catch {}
        // 最長保險：2.5s 後直接當作就緒，避免特定 UA 卡住事件
        setTimeout(() => { cleanup(); resolve(true) }, 2500)
      })
    }

    // 只負責「喚醒播放」— 不再動態塞 v.src，讓 <source> 自動挑格式
    const ensureMoonPlaying = async () => {
      const v = moonVideo.value
      if (!v) return
      try {
        if (v.readyState < 2) {
          v.load()
          await new Promise(res => v.addEventListener('canplay', res, { once: true }))
        }
        if (v.paused || v.ended) { try { v.currentTime = 0 } catch {} ; await v.play() }
      } catch {}
    }

    // 啟用 CSS mask 所需（保留）
    const onMoonVideoLoaded = () => {
      if (!moonVideoMask.value || !moonMaskContainer.value) return
      const video = moonVideoMask.value
      moonMaskContainer.value.style.setProperty('--ar', `${video.videoWidth}/${video.videoHeight}`)
    }

    // 多鏡頭檢查：支援度
    const facingModeSupported = computed(() => {
      try { return !!(navigator.mediaDevices?.getSupportedConstraints?.().facingMode) }
      catch { return false }
    })

    // 放在 defaultCheckMultipleCameras 上面：工具函式
    const normalizeVideoInputs = (devices) => {
      const vids = devices.filter(d => d.kind === 'videoinput')

      // 常見虛擬/轉接鏡頭關鍵字（大小寫不敏感）
      const VIRTUAL_RE = /(virtual|obs|ndi|snap\s*camera|manycam|xsplit|v4l2loopback|continuity|camo|reincubate|droidcam|ivcam|mmhmm|epocam|splitcam|altercam|webex|teams)/i

      // 規範化 label：移除括號與常見冗字，降低同一顆鏡頭不同寫法造成的重複
      const normalizeLabel = (s) => {
        if (!s) return ''
        return s
          .toLowerCase()
          .replace(/\(.*?\)/g, '')             // 括號內容
          .replace(/\b(built[-\s]*in|integrated|hd|full\s*hd|webcam|camera|facetime|usb\s*video\s*device)\b/g, '')
          .replace(/[\s_-]+/g, '')             // 空白/底線/連字號
          .trim()
      }

      // 先用 deviceId 去重，再用規範化後的 label 再去重一次
      const seenIds = new Set()
      const dedupById = vids.filter(d => d.deviceId && !seenIds.has(d.deviceId) && (seenIds.add(d.deviceId) || true))

      const seenLabels = new Set()
      const allVideos = dedupById.filter(d => {
        const norm = normalizeLabel(d.label || '')
        // 沒權限時 label 可能是空字串；允許一個空字串通過，避免全被砍光
        const key = norm || `__empty__-${d.deviceId}`
        if (seenLabels.has(key)) return false
        seenLabels.add(key)
        return true
      })

      // 濾掉虛擬鏡頭（包含 iPhone 連線 Continuity Camera）
      const realVideos = allVideos.filter(d => !VIRTUAL_RE.test(d.label || ''))

      return { allVideos, realVideos }
    }

    // ✅ 替換成這個版本（更嚴謹）
    const defaultCheckMultipleCameras = async () => {
      const md = navigator.mediaDevices
      if (!md?.enumerateDevices) return false

      try {
        const devices = await md.enumerateDevices()
        const { allVideos, realVideos } = normalizeVideoInputs(devices)

        // 更可靠的行動裝置判斷
        const ua = navigator.userAgent.toLowerCase()
        const uaMobile = /iphone|ipad|ipod|android/.test(ua)
        const isMobile = (navigator.userAgentData && typeof navigator.userAgentData.mobile === 'boolean')
          ? navigator.userAgentData.mobile
          : uaMobile

        if (isMobile) {
          // 手機：兩顆以上直接顯示；只回一顆但支援 facingMode（iOS 常見）也顯示
          if (allVideos.length >= 2 || realVideos.length >= 2) return true
          if (typeof navigator.mediaDevices?.getSupportedConstraints === 'function' &&
              !!navigator.mediaDevices.getSupportedConstraints().facingMode) {
            return true
          }
          return false
        } else {
          // 桌機：必須 ≥ 2 顆「真實」鏡頭才顯示，避免虛擬鏡頭/重複來源造成誤判
          return realVideos.length >= 2
        }
      } catch (e) {
        console.warn('enumerateDevices 檢查失敗：', e)
        return false
      }
    }

    // 執行多鏡頭檢查（可用父層自訂，否則 fallback）
    const runMultipleCamCheck = async () => {
      const fn = typeof props.checkMultipleCameras === 'function'
        ? props.checkMultipleCameras
        : defaultCheckMultipleCameras
      try {
        const ok = await fn()
        hasMultipleCamerasState.value = !!ok
        console.log('🎥 多鏡頭可切換：', hasMultipleCamerasState.value)
      } catch (err) {
        console.warn('多鏡頭檢查例外：', err)
        hasMultipleCamerasState.value = false
      }
    }

    // 對外提供節點
    expose({ moonVideo, ensureMoonPlaying, bgCanvas, maskCanvas, outputCanvas, contentFrame })

    // --- Lifecycle ---
    const preloadMoonIfNeeded = async () => {
      if (!needMoon.value) {
        moonReady.value = true // 不需要月亮就視為已就緒
        return
      }
      await nextTick()
      const v = moonVideo.value
      if (!v) {
        // 若此刻還沒產生 video 節點（幾乎不會），下一輪再試
        setTimeout(preloadMoonIfNeeded, 50)
        return
      }
      const ok = await waitForVideoReady(v)
      moonReady.value = !!ok
      if (moonReady.value) {
        try { await ensureMoonPlaying() } catch {}
        // 告知父層：若你要「等月亮載好才開相機」，請在收到這事件後再開相機
        emit('ready-for-camera')
      }
    }

    onMounted(() => {
      // 提示 10 秒後淡出
      setTimeout(() => { hintVisible.value = false; setTimeout(() => { showHintText.value = false }, 500) }, 10000)
      calculateTextScale()
      const handleResize = () => calculateTextScale()
      window.addEventListener('resize', handleResize)
      window.addEventListener('orientationchange', handleResize)

      // 頁面進入即預載月亮（若需要）
      preloadMoonIfNeeded()
    })

    onBeforeUnmount(() => {
      window.removeEventListener('resize', calculateTextScale)
      window.removeEventListener('orientationchange', calculateTextScale)
    })

    // 需要月亮的模式切換時，重新預載（避免使用者中途切到需要月亮的背景）
    watch(() => props.backgroundType, () => {
      moonReady.value = false
      preloadMoonIfNeeded()
    })

    // 相機與月亮皆備妥時，喚醒月亮播放
    watch(uiCameraRunning, async (ok) => {
      if (ok && needMoon.value) await ensureMoonPlaying()
    }, { immediate: true })

    // 相機跑起來（UI上）後再檢查是否有多顆鏡頭
    watch(uiCameraRunning, async (ok) => {
      if (ok) await runMultipleCamCheck()
    }, { immediate: true })

    // 回前景再喚醒
    if (typeof document !== 'undefined') {
      document.addEventListener('visibilitychange', () => {
        if (!document.hidden && uiCameraRunning.value && needMoon.value) ensureMoonPlaying()
      })
    }

    return {
      stage, contentFrame, bgCanvas, maskCanvas, outputCanvas,
      moonVideo, moonVideoMask, moonMaskContainer,
      showShareButton, showDownloadButton, showHintText, hintVisible,
      basePath, textScale,
      backgroundType: props.backgroundType, deviceType,
      onMoonVideoLoaded, showControls, cameraRunning,
      contentFrameStyle, needMoon, shutterIcon,
      hasMultipleCamerasState, switchCameraIcon,
      // 新增回傳到模板
      uiCameraRunning, loadingText, showLoadingOverlay
    }
  }
}
</script>

<style scoped>
/* 仍保留桌機 CSS Mask 區塊的樣式（目前關閉） */
.moon-mask-container { aspect-ratio: var(--ar, 16/9); }
.moon-video-masked{
  position:absolute; inset:0; object-fit:fill;
  -webkit-mask-image: radial-gradient(
    circle at calc(var(--cx, 50) * 1%) calc(var(--cy, 30) * 1%),
    rgba(0,0,0,1) 0 calc(var(--rpx, 100px) - var(--featherpx, 10px)),
    rgba(0,0,0,0) calc(var(--rpx, 100px) + var(--featherpx, 10px))
  );
  -webkit-mask-repeat:no-repeat;
  mask-image: radial-gradient(
    circle at calc(var(--cx, 50) * 1%) calc(var(--cy, 30) * 1%),
    rgba(0,0,0,1) 0 calc(var(--rpx, 100px) - var(--featherpx, 10px)),
    rgba(0,0,0,0) calc(var(--rpx, 100px) + var(--featherpx, 10px))
  );
  mask-repeat:no-repeat;
}
</style>