// usePreloadAssets.js - 预载入PhotoPreview页面资源
import { ref, computed } from 'vue'

export function usePreloadAssets() {
  const preloadProgress = ref(0)
  const totalAssets = ref(0)
  const loadedAssets = ref(0)
  const isPreloading = ref(false)

  const basePath = computed(() => import.meta.env.BASE_URL || '/')

  // 预载入图片
  const preloadImage = (src) => {
    return new Promise((resolve) => {
      if (!src) {
        resolve(null)
        return
      }

      const img = new Image()
      img.crossOrigin = 'anonymous'
      img.onload = () => {
        loadedAssets.value++
        console.log(`📷 载入图片成功: ${src} (${loadedAssets.value}/${totalAssets.value})`)
        resolve(img)
      }
      img.onerror = () => {
        loadedAssets.value++
        console.warn(`❌ 载入图片失败: ${src} (${loadedAssets.value}/${totalAssets.value})`)
        resolve(null)
      }
      img.src = src
    })
  }

  // 预载入视频
  const preloadVideo = (src) => {
    return new Promise((resolve) => {
      if (!src) {
        resolve(null)
        return
      }

      const video = document.createElement('video')
      video.muted = true
      video.preload = 'metadata'
      video.style.display = 'none'

      const cleanup = (success = true) => {
        document.body.removeChild(video)
        loadedAssets.value++
        if (success) {
          console.log(`🎬 载入视频成功: ${src} (${loadedAssets.value}/${totalAssets.value})`)
        } else {
          console.warn(`❌ 载入视频失败: ${src} (${loadedAssets.value}/${totalAssets.value})`)
        }
        resolve(success ? video : null)
      }

      video.onloadedmetadata = () => cleanup(true)
      video.onerror = () => cleanup(false)

      document.body.appendChild(video)
      video.src = src
    })
  }

  // PhotoPreview页面的背景配置（与useUI.js保持一致）
  const getAvailableBackgrounds = () => {
    return [
      {
        id: 'bg1',
        name: '月夜景觀',
        src: 'backgrounds/DefenderBg.png',
        frame: 'frames/bgDefender.png',
        contentArea: { x: 0.05, y: 0.25, width: 0.9, height: 0.5 },
        moonScale: 1.5
      },
      {
        id: 'bg2',
        name: '景色',
        src: 'backgrounds/DiscoveryBg.png',
        frame: 'frames/bgDiscovery.png',
        contentArea: { x: 0.05, y: 0.25, width: 0.9, height: 0.5 },
        moonScale: 1.5
      },
      {
        id: 'bg3',
        name: '城市',
        src: 'backgrounds/RangeBg.png',
        frame: 'frames/bgRangerover.png',
        contentArea: { x: 0.05, y: 0.25, width: 0.9, height: 0.5 },
        moonScale: 1.5
      }
    ]
  }

  // 开始预载入PhotoPreview资源
  const startPreloading = async () => {
    if (isPreloading.value) return

    console.log('🚀 开始预载入PhotoPreview资源...')
    isPreloading.value = true
    loadedAssets.value = 0

    const backgrounds = getAvailableBackgrounds()
    const preloadTasks = []

    // 计算总资源数量
    let assetCount = 0

    // 背景图片
    backgrounds.forEach(bg => {
      if (bg.src) assetCount++
      if (bg.frame) assetCount++
    })

    // 月亮视频文件
    const moonVideos = ['moon_alpha_ios.mov', 'moon.webm', 'moon.mp4']
    assetCount += moonVideos.length

    totalAssets.value = assetCount

    try {
      // 预载入背景图片和框架
      backgrounds.forEach(bg => {
        if (bg.src) {
          preloadTasks.push(preloadImage(basePath.value + bg.src))
        }
        if (bg.frame) {
          preloadTasks.push(preloadImage(basePath.value + bg.frame))
        }
      })

      // 预载入月亮视频文件
      moonVideos.forEach(videoFile => {
        preloadTasks.push(preloadVideo(basePath.value + videoFile))
      })

      // 并行载入所有资源
      await Promise.all(preloadTasks)

      console.log('✅ PhotoPreview资源预载入完成!')
      console.log(`📊 成功载入 ${loadedAssets.value}/${totalAssets.value} 个资源`)

    } catch (error) {
      console.warn('⚠️ 部分资源预载入失败:', error)
    } finally {
      isPreloading.value = false
    }
  }

  // 计算预载入进度
  const progressPercentage = computed(() => {
    if (totalAssets.value === 0) return 0
    return Math.round((loadedAssets.value / totalAssets.value) * 100)
  })

  return {
    startPreloading,
    preloadProgress: progressPercentage,
    totalAssets,
    loadedAssets,
    isPreloading
  }
}