<template>
  <div id="app" class="h-screen w-screen bg-app-bg text-app-fg overflow-hidden">
    <!-- Landing Page -->
    <LandingPage 
      v-if="!showCameraApp"
      @start-camera="handleStartCamera"
    />
    
    <!-- Camera App -->
    <div v-else>
      <!-- Header - 隱藏 -->
      <!-- <AppHeader 
        :status="detectionStatus"
        :mobile-menu-open="mobileMenuOpen"
        @toggle-menu="toggleMobileMenu"
      /> -->

      <!-- Main Layout -->
      <main class="h-screen w-screen overflow-hidden">
        <!-- Camera Stage -->
        <CameraStage
          @ready-for-camera="startCamera()"
          ref="cameraStageRef"
          class="relative bg-black overflow-hidden w-screen h-screen"
          :background-type="backgroundType"
          :is-i-o-s-device="isIOSDevice"
          :show-controls="!showPhotoPreview && !showProgressModal && !showCaptureConfirm"
          :camera-running="cameraRunning"
          :desktop-max-width="480"
          :check-multiple-cameras="checkMultipleCameras"
          @capture-photo="capturePhoto"
          @share-video="shareVideo"
          @download-video="downloadVideo"
          @switch-camera="switchCamera"
        />
      </main>

      <!-- Mobile Scrim -->
      <div 
        v-show="mobileMenuOpen" 
        class="fixed inset-0 bg-black bg-opacity-40 backdrop-blur-sm z-40 lg:hidden"
        @click="toggleMobileMenu"
      />

      <!-- Modal Components -->
      <LoadingModal 
        v-if="showLoadingModal" 
        :message="loadingMessage" 
      />
      
      <ProgressModal 
        v-if="showProgressModal" 
        :progress="recordingProgress"
        :status="progressStatus"
        :show-controls="showProgressControls"
        @close="closeProgressModal"
        @share="shareFromModal"
        @download="downloadFromModal"
      />

      <!-- Photo Capture Confirmation -->
      <CaptureConfirmation
        v-if="showCaptureConfirm"
        :image-data="capturedImageData"
        :is-i-o-s-device="isIOSDevice"
        :has-person="capturedImageData?.hasPerson"
        @retake="retakePhoto"
        @next="proceedToPreview"
      />

      <!-- Photo Preview Modal -->
      <PhotoPreview
        v-if="showPhotoPreview"
        :original-image-data="previewImageData"
        :available-backgrounds="availableBackgrounds"
        :selected-background="selectedBackground"
        :user-name="userName"
        :has-person="previewImageData?.hasPerson"
        @close="hidePreview"
        @background-change="selectBackground"
      />

      <!-- Hidden DOM elements needed by segmentationCore.js -->
      <div class="hidden">
        <video ref="videoEl" class="input_video" playsinline />
        
        <video
          ref="bgVideoEl"
          class="bg_video"
          playsinline
          muted
          loop
          preload="auto"
          src="https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4"
        />

        <video
          ref="bgMoonVideoEl"
          class="bg_video"
          muted
          loop
          preload="auto"
          playsinline
          style="display: none;"
        >
        </video>
        
        <!-- iOS 專用透明 MOV 月亮影片 -->
        <video
          ref="iosMoonVideoEl"
          class="bg_video"
          muted
          loop
          preload="auto"
          playsinline
          webkit-playsinline
          style="display: none; pointer-events: none; background: transparent;"
        >
        </video>
      </div>
    </div>
  </div>
</template>

<script>
import { ref, onMounted, onBeforeUnmount, nextTick, watch } from 'vue'
import LandingPage from './components/LandingPage.vue'
import AppHeader from './components/AppHeader.vue'
import ControlPanel from './components/ControlPanel.vue'
import CameraStage from './components/CameraStage.vue'
import StatusBar from './components/StatusBar.vue'
import LoadingModal from './components/LoadingModal.vue'
import ProgressModal from './components/ProgressModal.vue'
import PhotoPreview from './components/PhotoPreview.vue'
import CaptureConfirmation from './components/CaptureConfirmation.vue'
import { useMediaPipe } from './composables/useMediaPipe'
import { useUI } from './composables/useUI'
import { usePreloadAssets } from './composables/usePreloadAssets'

export default {
  name: 'App',
  components: {
    LandingPage,
    AppHeader,
    ControlPanel,
    CameraStage,
    StatusBar,
    LoadingModal,
    ProgressModal,
    PhotoPreview,
    CaptureConfirmation
  },
  setup() {
    // Page state
    const showCameraApp = ref(false)
    const userName = ref('')
    
    // Template refs
    const videoEl = ref(null)
    const bgVideoEl = ref(null)
    const bgMoonVideoEl = ref(null)
    const iosMoonVideoEl = ref(null)
    const fullscreenMoonEl = ref(null)
    const cameraStageRef = ref(null)
    
    // Base path for assets
    const basePath = import.meta.env.BASE_URL || '/'
    
    // iOS 設備檢測
    const detectIOSDevice = () => {
      const userAgent = navigator.userAgent.toLowerCase()
      const isIOS = /iphone|ipad|ipod/.test(userAgent)
      const isLineApp = /line/.test(userAgent)
      const isChrome = /crios/.test(userAgent)
      const isSafari = /safari/.test(userAgent) && !/chrome/.test(userAgent)
      const urlParams = new URLSearchParams(window.location.search)
      const isTestMode = urlParams.get('test-mov') === '1'
      return (isIOS && (isLineApp || isChrome || isSafari)) || isTestMode
    }
    
    const isIOSDevice = ref(detectIOSDevice())
    
    // Handle start camera from landing page
    const handleStartCamera = async (name) => {
      userName.value = name
      showCameraApp.value = true
      await nextTick()
      try {
        await startCamera()
        updateBackgroundType('custom_moon_bg')
        updateSegmentation(false)

        // 🚀 相机启动后，开始预载入PhotoPreview资源（非阻塞）
        setTimeout(() => {
          startPreloading().catch(err =>
            console.warn('预载入PhotoPreview资源失败:', err)
          )
        }, 2000) // 延迟2秒，让相机先稳定启动

      } catch (error) {
        console.error('❌ 自動啟動失敗:', error)
      }
    }

    const handleMovError = (event) => {
      console.error('🎬 MOV 載入錯誤:', event.target.error)
      console.log('🎬 嘗試載入的路徑:', event.target.src)
    }
    const handleMovLoadStart = (event) => { console.log('🎬 MOV 開始載入:', event.target.src) }
    const handleMovCanPlay = (event) => { console.log('🎬 MOV 可以播放:', event.target.src) }

    // 预载入PhotoPreview资源
    const { startPreloading, preloadProgress, isPreloading } = usePreloadAssets()

    // UI state
    const {
      mobileMenuOpen,
      detectionStatus,
      statusText,
      showLoadingModal,
      loadingMessage,
      showProgressModal,
      recordingProgress,
      progressStatus,
      showProgressControls,
      showCaptureConfirm,
      capturedImageData,
      showPhotoPreview,
      previewImageData,
      availableBackgrounds,
      selectedBackground,
      toggleMobileMenu,
      closeProgressModal,
      shareFromModal,
      downloadFromModal,
      showCaptureConfirmation,
      retakePhoto,
      proceedToPreview,
      showPreview,
      hidePreview,
      selectBackground,
      createPhotoFlashEffect,
      initKeyboardShortcuts,
      cameraControls
    } = useUI()

    // MediaPipe
    const mediaPipeComposable = useMediaPipe({
      detectionStatus,
      statusText,
      showProgressModal,
      recordingProgress,
      progressStatus,
      showProgressControls,
      showCaptureConfirmation
    })
    
    const {
      cameraRunning,
      segmentationEnabled,
      showMask,
      backgroundType,
      effectIntensity,
      edgeFeather,
      temporalSmooth,
      threshold,
      faceCount,
      facesInArea,
      startCamera,
      stopCamera,
      switchCamera,
      updateSegmentation,
      updateShowMask,
      updateBackgroundType,
      updateEffectIntensity,
      updateEdgeFeather,
      updateTemporalSmooth,
      updateThreshold,
      capturePhoto,
      toggleMask,
      shareVideo,
      downloadVideo,
      initMediaPipe,
      handleResize,
      testMovBackground,
      checkMultipleCameras
    } = mediaPipeComposable

    cameraControls.value = {
      startCamera,
      stopCamera,
      updateBackgroundType,
      updateSegmentation,
      ensureMoonPlaying: () => cameraStageRef.value?.ensureMoonPlaying?.()
    }

    const initializeCameraApp = async () => {
      await nextTick()
      if (bgMoonVideoEl.value) {
        const base = import.meta.env.BASE_URL || '/'
        bgMoonVideoEl.value.src = base + 'moon.mp4'
      }
      if (iosMoonVideoEl.value && isIOSDevice.value) {
        const base = import.meta.env.BASE_URL || '/'
        iosMoonVideoEl.value.src = base + 'moon_alpha_ios.mov'
      }
      initKeyboardShortcuts({ startCamera, stopCamera, switchCamera, capturePhoto, cameraRunning })
      await nextTick()
      if (!cameraStageRef.value) {
        setTimeout(initializeCameraApp, 200)
        return
      }
      const elements = {
        videoEl: videoEl.value,
        bgCanvas: cameraStageRef.value?.bgCanvas,
        maskCanvas: cameraStageRef.value?.maskCanvas,
        outCanvas: cameraStageRef.value?.outputCanvas,
        bgVideoEl: bgVideoEl.value,
        bgMoonVideoEl: bgMoonVideoEl.value,
        iosMoonVideoEl: iosMoonVideoEl.value,
        fullscreenMoonEl: cameraStageRef.value?.moonVideo,
        isIOSDevice: isIOSDevice.value
      }
      try { await initMediaPipe(elements) } catch (e) { console.error('❌ MediaPipe 初始化失敗:', e) }
      window.addEventListener('resize', handleResize)
      setTimeout(() => { startCamera() }, 500)
    }

    const initCameraAppOnShow = () => { if (showCameraApp.value) setTimeout(initializeCameraApp, 100) }

    onMounted(() => { watch(showCameraApp, initCameraAppOnShow) })
    onBeforeUnmount(() => { window.removeEventListener('resize', handleResize) })

    return {
      showCameraApp,
      userName,
      handleStartCamera,
      videoEl, bgVideoEl, bgMoonVideoEl, iosMoonVideoEl, fullscreenMoonEl, cameraStageRef,
      mobileMenuOpen, detectionStatus, statusText, showLoadingModal, loadingMessage, showProgressModal,
      recordingProgress, progressStatus, showProgressControls, showCaptureConfirm, capturedImageData,
      showPhotoPreview, previewImageData, availableBackgrounds, selectedBackground, toggleMobileMenu,
      closeProgressModal, shareFromModal, downloadFromModal, showCaptureConfirmation, retakePhoto,
      proceedToPreview, showPreview, hidePreview, selectBackground, createPhotoFlashEffect,
      cameraRunning, segmentationEnabled, showMask, backgroundType, effectIntensity, edgeFeather,
      temporalSmooth, threshold, faceCount, facesInArea, basePath, isIOSDevice,
      startCamera, stopCamera, switchCamera, updateSegmentation, updateShowMask, updateBackgroundType,
      updateEffectIntensity, updateEdgeFeather, updateTemporalSmooth, updateThreshold, capturePhoto,
      toggleMask, shareVideo, downloadVideo, testMovBackground, handleMovError, handleMovLoadStart, handleMovCanPlay
    }
  }
}
</script>