<template>
  <!-- 舞台：黑底滿版（桌機左右黑邊的來源），內容置中 -->
  <section class="stage fixed inset-0 bg-black overflow-hidden z-[50] w-[100dvw] h-[100dvh]"
           style="width:100vw;width:100dvw;height:100vh;height:100dvh">
    <!-- 置中互動區（桌機限制寬度；手機仍滿版） -->
    <div
      ref="contentFrame"
      class="content-frame absolute inset-y-0 left-1/2 -translate-x-1/2 z-[3]"
      :style="contentFrameStyle"
    >
      <!-- 背景：拍到的原始相機畫面，只鋪在 content 區 -->
      <img
        v-if="imageData && imageData.originalImageData"
        :src="imageData.originalImageData"
        class="absolute inset-0 w-full h-full object-cover z-[1] pointer-events-none"
        style="transform: scaleX(-1); background: transparent;"
      />

      <!-- ✅ 月亮影片覆蓋層（所有裝置統一用 <source> 列表：MOV(hvc1) → WEBM → MP4）
           桌機會優先吃 .mov；不支援就自動 fallback -->
      <div
        v-if="hasPerson"
        class="absolute inset-0 pointer-events-none z-[2]"
      >
        <video
          ref="moonVideo"
          class="w-full h-full object-contain force-composite"
          autoplay
          loop
          muted
          playsinline
          webkit-playsinline
          preload="auto"
          style="pointer-events:none; background:transparent; mix-blend-mode:normal;"
        >
          <!-- 先給 hvc1 透明影片；Safari (含 macOS 桌機) 會吃，其他瀏覽器會跳過 -->
          <source :src="basePath + 'moon_alpha_ios.mov'" type='video/mp4; codecs="hvc1"' />
          <!-- 再給 webm；多數 Chrome/Android/桌機可播放 -->
          <source :src="basePath + 'moon.webm'" type="video/webm" />
          <!-- 最後 mp4 當保底 -->
          <source :src="basePath + 'moon.mp4'" type="video/mp4" />
        </video>
      </div>

      <!-- ⚠️（保留）桌機 CSS Mask 版本：目前關閉，有需要再打開 -->
      <div
        v-if="false && hasPerson && deviceType === 'other'"
        class="moon-mask-container absolute inset-0 pointer-events-none z-[2]"
        ref="moonMaskContainer"
      >
        <video
          ref="moonVideoMask"
          class="moon-video-masked w-full h-full"
          autoplay
          loop
          muted
          playsinline
          webkit-playsinline
          style="pointer-events:none;"
          :src="basePath + 'moon.mp4'"
          @loadedmetadata="onMoonVideoLoaded"
        />
      </div>

      <!-- 人像覆蓋層（不吃點擊） - 只在有人像且有分割數據時顯示 -->
      <img
        v-if="hasPerson && imageData && imageData.segmentedImageData"
        :src="imageData.segmentedImageData"
        class="absolute inset-0 w-full h-full object-cover z-[3] pointer-events-none"
        style="background: transparent;"
      />

      <!-- 底部按鈕區域的半透明遮罩（只覆蓋 content-frame 底部） -->
      <div class="absolute left-0 right-0 bottom-0 h-32 bg-gradient-to-t from-black/80 to-transparent z-[4] pointer-events-none"></div>

      <!-- 確認按鈕區域（置中容器內） -->
      <div class="absolute left-0 right-0 z-[5] pt-4 pb-6"
           :style="{ bottom: `calc(env(safe-area-inset-bottom,0px) + 0px)`, paddingBottom: `calc(1rem + env(safe-area-inset-bottom,0px))` }">
        <div class="mx-auto max-w-[600px] flex flex-row items-center justify-around px-2">
          <button
            @click="onRetake"
            class="flex-1 max-w-[150px] py-3 bg-white text-black rounded-[5px] font-medium text-[13px] sm:text-[15px]
                   border border-gray-300 hover:bg-gray-100 transition-colors
                   inline-flex items-center justify-center gap-1"
          >
            <span class="whitespace-nowrap">再拍一次</span>
            <svg class="w-3 h-3 sm:w-4 sm:h-4" viewBox="0 0 24 24" fill="none"
                 stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">
              <polyline points="9 18 15 12 9 6" />
            </svg>
          </button>

          <button
            @click="onNext"
            class="flex-1 max-w-[150px] py-3 bg-white text-black rounded-[5px] font-medium text-[13px] sm:text-[15px]
                   border border-gray-300 hover:bg-gray-100 transition-colors
                   inline-flex items-center justify-center gap-1"
          >
            <span class="whitespace-nowrap">下一步</span>
            <svg class="w-3 h-3 sm:w-4 sm:h-4" viewBox="0 0 24 24" fill="none"
                 stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">
              <polyline points="9 18 15 12 9 6" />
            </svg>
          </button>
        </div>
      </div>
    </div>
  </section>
</template>

<script>
import { ref, computed, onMounted, onBeforeUnmount } from 'vue'

export default {
  name: 'CaptureConfirmation',
  props: {
    imageData: { type: Object, default: () => ({}) },
    isIOSDevice: { type: Boolean, default: false },
    hasPerson: { type: Boolean, default: true },
    /** 桌機版互動區最大寬度（px），手機不受影響 */
    desktopMaxWidth: { type: [Number, String], default: 480 }
  },
  emits: ['retake', 'next'],
  setup(props, { emit }) {
    const basePath = computed(() => import.meta.env.BASE_URL || '/')

    // 置中 content-frame 寬度（桌機限制、手機 100vw）
    const contentFrameStyle = computed(() => ({
      width: `min(100vw, ${Number(props.desktopMaxWidth) || 480}px)`,
      height: '100%',
      background: 'transparent'
    }))

    // Template refs
    const moonVideo = ref(null)
    const moonVideoMask = ref(null)
    const moonMaskContainer = ref(null)

    // 簡單設備類型（僅保留：給保留的 CSS-mask 區塊使用；預設判 'other' 為桌機）
    const deviceType = computed(() => {
      const ua = navigator.userAgent.toLowerCase()
      const isIOS = /iphone|ipad|ipod/.test(ua)
      const isAndroid = /android/.test(ua)
      if (isIOS) return 'ios'
      if (isAndroid) return 'android'
      return 'other'
    })

    // （保留）桌機 CSS Mask 參數
    const maskParams = ref({ nx: 0.50, ny: 0.30, nr: 0.15, featherRatio: 0.03 })
    const updateMask = () => {
      if (!moonMaskContainer.value) return
      const container = moonMaskContainer.value
      const rect = container.getBoundingClientRect()
      const minSide = Math.min(rect.width, rect.height)
      container.style.setProperty('--cx', (maskParams.value.nx * 100).toFixed(4))
      container.style.setProperty('--cy', (maskParams.value.ny * 100).toFixed(4))
      container.style.setProperty('--rpx', (maskParams.value.nr * minSide) + 'px')
      container.style.setProperty('--featherpx', (maskParams.value.featherRatio * minSide) + 'px')
    }
    const onMoonVideoLoaded = () => {
      if (!moonVideoMask.value || !moonMaskContainer.value) return
      const video = moonVideoMask.value
      const container = moonMaskContainer.value
      container.style.setProperty('--ar', `${video.videoWidth}/${video.videoHeight}`)
      updateMask()
    }

    const onRetake = () => emit('retake')
    const onNext = () => emit('next')

    onMounted(() => {
      // 只有保留區塊才需要
      const handleResize = () => updateMask()
      window.addEventListener('resize', handleResize)
      window.addEventListener('orientationchange', handleResize)
      setTimeout(updateMask, 50)
    })
    onBeforeUnmount(() => {
      window.removeEventListener('resize', updateMask)
      window.removeEventListener('orientationchange', updateMask)
    })

    return {
      basePath,
      deviceType,
      moonVideo, moonVideoMask, moonMaskContainer,
      onMoonVideoLoaded,
      onRetake, onNext,
      hasPerson: props.hasPerson,
      contentFrameStyle
    }
  }
}
</script>

<style scoped>
/* （保留）乾淨透明的月亮遮罩容器 */
.moon-mask-container {
  position: absolute;
  inset: 0;
  background: transparent !important;
}

/* （保留）視訊以 cover + 圓形漸層遮罩 */
.moon-video-masked {
  position: absolute;
  inset: 0;
  object-fit: cover;
  background: transparent !important;

  -webkit-mask-image: radial-gradient(
    circle at calc(var(--cx, 50) * 1%) calc(var(--cy, 30) * 1%),
    rgba(0,0,0,1) 0 calc(var(--rpx, 100px) - var(--featherpx, 10px)),
    rgba(0,0,0,0) calc(var(--rpx, 100px) + var(--featherpx, 10px))
  );
  -webkit-mask-repeat: no-repeat;
  mask-image: radial-gradient(
    circle at calc(var(--cx, 50) * 1%) calc(var(--cy, 30) * 1%),
    rgba(0,0,0,1) 0 calc(var(--rpx, 100px) - var(--featherpx, 10px)),
    rgba(0,0,0,0) calc(var(--rpx, 100px) + var(--featherpx, 10px))
  );
  mask-repeat: no-repeat;
}

/* （開發輔助圈：預設關閉） */
.moon-mask-container::after { display: none; }
</style>